/* YARDIVO STYLE: anonymous */

:root{--bg:#07111d;--bg2:#091827;--panel:#0b1623;--panel2:#0d1b2a;--line:#1c2c3c;--line2:#233749;--text:#f7f9fc;--muted:#8fa2b7;--blue:#1f7cf5;--blue2:#0d5bc6;--green:#31d16b;--red:#ff424c;--orange:#ff922b;--purple:#9e61ff;--yellow:#ffc02e}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:radial-gradient(circle at 65% 0%,#0c2237 0,#07111d 32%,#050b12 100%);color:var(--text)}button,input,select{font:inherit}.app-shell{display:grid;grid-template-columns:252px 1fr;min-height:100vh}.sidebar{position:sticky;top:0;height:100vh;overflow-y:auto;background:linear-gradient(180deg,#071524 0%,#06101b 100%);border-right:1px solid #14283a;padding:22px 14px 18px;display:flex;flex-direction:column;box-shadow:12px 0 40px rgba(0,0,0,.16)}.brand-row{display:flex;align-items:center;gap:8px;padding:2px 8px 22px}.brand-mark{font-size:31px;font-weight:900;letter-spacing:.5px}.brand-slash{font-size:29px;line-height:1;color:var(--blue);font-weight:900;transform:skew(-12deg)}.brand-sub{font-size:10px;font-weight:700;line-height:1.2;max-width:88px;color:#dfe8f2}.nav{display:grid;gap:4px}.nav-btn{position:relative;display:flex;align-items:center;gap:12px;width:100%;border:1px solid transparent;background:transparent;color:#d7e2ed;padding:11px 13px;border-radius:7px;text-align:left;cursor:pointer;font-size:14px;transition:.2s}.nav-btn span{width:19px;text-align:center;color:#c6d4e1;font-size:17px}.nav-btn:hover{background:#0b2035;border-color:#163a5a}.nav-btn.active{background:linear-gradient(90deg,#0d69d7,#0754ab);border-color:#197be4;color:white;box-shadow:0 8px 25px rgba(0,91,202,.18)}.nav-badge{margin-left:auto;background:#ff313a;border-radius:5px;padding:2px 7px;font-size:11px}.sidebar-footer{margin-top:auto;border-top:1px solid #15283a;padding:18px 10px 4px;color:var(--muted);font-size:12px;line-height:1.6}.sidebar-footer strong{color:var(--green);font-size:12px}.sidebar-footer p{margin:3px 0}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:7px}.green{background:var(--green);box-shadow:0 0 12px rgba(49,209,107,.65)}
.main{min-width:0}.topbar{height:64px;padding:0 22px;border-bottom:1px solid #172839;display:flex;align-items:center;justify-content:space-between;background:rgba(5,13,22,.84);backdrop-filter:blur(16px);position:sticky;top:0;z-index:20}.topbar h1{display:inline-block;font-size:21px;margin:0 12px 0 0}.subtitle{color:var(--muted);font-size:13px}.top-actions{display:flex;align-items:center;gap:12px}.clock{text-align:right;display:grid}.clock strong{font-size:14px}.clock small{color:#91a7bb;font-size:10px}.live{border:1px solid #155c36;background:#08271b;color:#57e987;border-radius:5px;padding:6px 9px;font-size:11px;font-weight:800}.live i{display:inline-block;width:7px;height:7px;background:#3edf76;border-radius:50%;margin-right:5px;box-shadow:0 0 10px #3edf76}.primary{border:1px solid #2988f4;background:linear-gradient(180deg,#1479e8,#0b5cb6);color:white;padding:9px 13px;border-radius:6px;cursor:pointer;font-weight:700;box-shadow:0 8px 25px rgba(0,102,217,.18)}.view{display:none;padding:16px}.view.active{display:block}
.stats{display:grid;grid-template-columns:repeat(6,minmax(150px,1fr));gap:10px;margin-bottom:10px}.stat{min-height:104px;background:linear-gradient(180deg,#0c1825,#0a1521);border:1px solid #1b2b3b;border-radius:6px;padding:14px 16px;display:grid;grid-template-columns:42px 1fr;align-items:center;gap:10px;box-shadow:0 8px 18px rgba(0,0,0,.08)}.stat-icon{font-size:29px;text-align:center}.stat-icon.blue{color:#2a8bff}.stat-icon.orange{color:var(--orange)}.stat-icon.green{color:var(--green)}.stat-icon.purple{color:var(--purple)}.stat .label{font-size:10px;letter-spacing:.25px;color:#c8d2dc;text-transform:uppercase}.stat .value{font-size:25px;font-weight:800;line-height:1.1;margin:4px 0}.stat .note{font-size:10px;color:var(--muted)}.stat .note.danger{color:#ff515a}.stat .note.success{color:#49df79}
.dashboard-grid{display:grid;grid-template-columns:minmax(0,2.45fr) minmax(300px,.78fr);gap:10px}.left-col,.right-col{display:grid;gap:10px;align-content:start}.panel{background:linear-gradient(180deg,#0a1622,#09131e);border:1px solid #1b2c3c;border-radius:6px;box-shadow:0 12px 28px rgba(0,0,0,.1);overflow:hidden}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 14px}.panel-head h2{margin:0;font-size:14px;letter-spacing:.2px}.panel-head small{font-size:10px;font-weight:500;color:#a5b6c6}.panel-head a{color:#298bff;font-size:11px;cursor:pointer}.table-tools input,.panel-head>input{width:230px;background:#07111c;color:white;border:1px solid #213447;border-radius:5px;padding:8px 10px;font-size:11px;outline:none}.dock-overview{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;padding:2px 12px 8px}.dock-card{border:1px solid #24394b;border-radius:5px;min-height:146px;background:linear-gradient(180deg,#0d1a27,#0a141f);padding:11px 10px;display:flex;flex-direction:column;text-align:center}.dock-card h3{margin:0;font-size:11px;font-weight:700}.dock-status{font-size:14px;font-weight:800;margin:10px 0 7px;padding-bottom:7px;border-bottom:2px solid}.dock-card.busy .dock-status{color:var(--red);border-color:var(--red)}.dock-card.free .dock-status{color:var(--green);border-color:var(--green)}.dock-card .truckline{font-size:10px;color:#edf4fa;line-height:1.5}.dock-card .truckline span{display:block;color:#98a9b8}.dock-card .mode{margin-top:auto;border-top:1px solid #16283a;padding-top:7px;font-size:9px;font-weight:700;color:#ff525b}.dock-card.free .mode{color:#43db73}.legend{display:flex;gap:23px;padding:4px 14px 12px;color:#9eb0c1;font-size:10px}.legend span{display:flex;align-items:center;gap:7px}.l{display:inline-block;width:10px;height:10px}.l.free{background:#2ebc5b}.l.red{background:#d9323c}.l.orange{background:#ec7f1d}.l.gray{background:#41576c}.l.blue{background:#1265ba}
.table-wrap{overflow:auto;padding:0 12px 10px}table{width:100%;border-collapse:collapse;font-size:10px}thead th{font-size:8.5px;font-weight:500;color:#b4c3d0;text-align:left;padding:7px 7px;border:1px solid #192c3e;background:#0b1724;white-space:nowrap}tbody td{padding:5px 7px;border:1px solid #172a3b;color:#d8e3ed;white-space:nowrap}tbody tr:hover{background:#0d2133}.badge{display:inline-flex;align-items:center;justify-content:center;min-width:64px;padding:3px 7px;border-radius:4px;font-size:8px;font-weight:800;border:1px solid}.U dolasku{color:#6eb3ff;border-color:#215d9e;background:#0d3158}.Na čekanju{color:#ffd250;border-color:#6c5815;background:#4a3a08}.AtDock{color:#ff8080;border-color:#8d2929;background:#4f1719}.Završeno{color:#8bf1ad;border-color:#206c3b;background:#103a23}.action{border:1px solid #285d8e;background:#0a2945;color:#7fc0ff;border-radius:4px;padding:4px 7px;font-size:8px;cursor:pointer}.priority{display:inline-block;border:1px solid;border-radius:4px;padding:3px 6px;font-size:8px}.priority.high{color:#ff6565;border-color:#9b3333}.priority.medium{color:#ffc24c;border-color:#80611f}.priority.low{color:#4de282;border-color:#217b43}.op{background:#31174d;color:#d69bff;border:1px solid #522873;padding:3px 7px;border-radius:4px;font-size:8px}
.alert{display:grid;grid-template-columns:32px 1fr auto;gap:9px;align-items:center;padding:12px 14px;border-top:1px solid #1b2e40}.alert b{font-size:25px}.alert div{display:grid}.alert strong{font-size:11px}.alert span{font-size:10px;color:#a5b6c6;margin-top:2px}.alert time{font-size:10px;color:#9db0c2}.alert.danger b{color:#ff424c}.alert.warning b{color:#ff922b}.alert.info b{color:#2b91ff}.recommendation{padding-bottom:10px}.recommend-card{margin:0 12px 8px;border:1px solid #203549;border-radius:5px;padding:14px;display:grid;grid-template-columns:88px 1fr;gap:14px;align-items:center}.dock-icon{font-size:54px;color:var(--green);border-right:1px solid #22384a;height:100%;display:flex;align-items:center;justify-content:center}.recommend-card small{font-size:9px;color:#a9b9c6}.recommend-card h3{font-size:22px;color:var(--green);margin:5px 0 7px}.recommend-card p{font-size:10px;color:#aab8c5;margin:5px 0}.recommend-card strong{font-size:11px}.recommend-btn{display:block;width:calc(100% - 24px);margin:0 12px;border:1px solid #2384f3;color:#4aa1ff;background:#082343;padding:9px;border-radius:5px;font-size:11px;font-weight:800;cursor:pointer}.terminal-info{padding-bottom:12px}.info-row{display:flex;justify-content:space-between;padding:8px 13px;margin:0 12px;border-top:1px solid #1a2e40;font-size:11px}.info-row span{color:#9cafbf}.danger-text{color:#ff4d42}.planner{padding:0 12px 7px;overflow:auto}.planner-grid{min-width:760px;display:grid;grid-template-columns:36px repeat(14,1fr);grid-auto-rows:22px;border-top:1px solid #1a2c3c;border-left:1px solid #1a2c3c}.planner-grid>div{border-right:1px solid #17293a;border-bottom:1px solid #17293a;font-size:8px;display:flex;align-items:center;justify-content:center;color:#cad6e0}.planner-grid .time{background:#0b1723;color:#c2d0dd}.planner-grid .dock-label{font-weight:700;background:#0b1723}.slotbar{margin:3px 2px;border-radius:3px;font-weight:700;color:white!important}.slotbar.red{background:linear-gradient(90deg,#762025,#a32930)}.slotbar.blue{background:linear-gradient(90deg,#0a3e7b,#0b5baa)}.slotbar.green{background:linear-gradient(90deg,#0e4e29,#12743a)}
.cards,.yard-grid,.dock-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px;padding:0 14px 14px}.card,.slot{background:#0c1a27;border:1px solid #20374a;border-radius:7px;padding:15px}.card h3,.slot-title{margin:0 0 8px}.meta,.slot-truck{color:#9fb2c3;font-size:12px;line-height:1.6}.slot.occupied{border-color:#b73940;box-shadow:inset 0 0 0 1px rgba(255,65,75,.12)}
dialog{width:min(460px,calc(100vw - 30px));border:1px solid #27435a;border-radius:10px;background:#091521;color:white;padding:0;box-shadow:0 30px 90px rgba(0,0,0,.65)}dialog::backdrop{background:rgba(0,6,12,.8);backdrop-filter:blur(5px)}form{padding:22px;display:grid;gap:12px}.modal-head{display:flex;justify-content:space-between;align-items:flex-start}.modal-head small{color:#2d94ff;font-size:9px}.modal-head h2{margin:3px 0 0}.icon-btn,.secondary{border:1px solid #284158;background:#0b1926;color:#d9e6ef;border-radius:5px;cursor:pointer}.icon-btn{width:32px;height:32px;font-size:21px}.secondary{padding:9px 13px}label{display:grid;gap:5px;color:#b9c8d5;font-size:11px}input,select{background:#07111c;color:white;border:1px solid #243c51;border-radius:5px;padding:10px;outline:none}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.dialog-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:4px}
@media(max-width:1180px){.stats{grid-template-columns:repeat(3,1fr)}.dashboard-grid{grid-template-columns:1fr}.dock-overview{grid-template-columns:repeat(3,1fr)}.right-col{grid-template-columns:repeat(3,1fr)}.right-col .alerts-panel{grid-column:span 3}}
@media(max-width:800px){.app-shell{grid-template-columns:1fr}.sidebar{position:relative;height:auto}.nav{grid-template-columns:repeat(2,1fr)}.sidebar-footer{display:none}.topbar{position:relative;height:auto;padding:14px 16px;gap:10px;align-items:flex-start}.top-actions{flex-wrap:wrap;justify-content:flex-end}.view{padding:10px}.stats{grid-template-columns:repeat(2,1fr)}.dock-overview{grid-template-columns:repeat(2,1fr)}.right-col{grid-template-columns:1fr}.right-col .alerts-panel{grid-column:auto}.panel-head{align-items:flex-start}.table-tools input{width:160px}}
@media(max-width:520px){.stats{grid-template-columns:1fr}.dock-overview{grid-template-columns:1fr}.brand-sub{display:none}.nav{grid-template-columns:1fr 1fr}.primary{font-size:11px}.clock{display:none}.form-grid{grid-template-columns:1fr}}

  
.notice-layout{display:grid;grid-template-columns:minmax(360px,.85fr) minmax(520px,1.4fr);gap:12px}
.notice-form{padding:16px;display:grid;gap:12px}
.notice-form .form-grid{grid-template-columns:1fr 1fr}
.notice-result{margin:0 16px 16px;padding:14px;border:1px solid #24405a;border-radius:7px;background:#081521}
.notice-result.good{border-color:#1f8b4b;background:#082218}
.notice-result.bad{border-color:#b83943;background:#2b1015}
.notice-result.info{border-color:#246fb7;background:#0a2036}
.notice-result h3{margin:0 0 7px;font-size:13px}
.notice-result p{margin:3px 0;color:#bed0df;font-size:11px;line-height:1.5}
.notice-actions{display:flex;gap:8px;flex-wrap:wrap}
.notice-table-wrap{overflow:auto}
.notice-table{width:100%;border-collapse:collapse;min-width:820px}
.notice-table th,.notice-table td{padding:10px 9px;border-top:1px solid #192c3d;text-align:left;font-size:10px}
.notice-table th{color:#8fa6ba;font-size:9px;letter-spacing:.4px}
.notice-table td{color:#dce7ef}
.notice-pill{display:inline-flex;padding:3px 7px;border-radius:999px;font-size:9px;font-weight:800}
.notice-pill.ok{background:#0d3c25;color:#4ce184;border:1px solid #17633a}
.notice-pill.warn{background:#40230d;color:#ffb35c;border:1px solid #704017}
.schedule-board{overflow:auto;padding:0 12px 14px}
.schedule-grid{min-width:920px;display:grid;grid-template-columns:70px repeat(28,minmax(29px,1fr));grid-auto-rows:42px;border-left:1px solid #173047;border-top:1px solid #173047}
.schedule-grid>div{border-right:1px solid #173047;border-bottom:1px solid #173047;display:flex;align-items:center;justify-content:center;font-size:8px;overflow:hidden}
.schedule-grid .head{background:#0d1c2a;color:#a9bbca;grid-row:1}
.schedule-grid .ramp{background:#0d1c2a;color:white;font-weight:800}
.schedule-grid .booked{margin:4px 2px;border-radius:4px;background:linear-gradient(90deg,#0c559d,#157ad4);color:white!important;font-weight:800;padding:2px 4px;white-space:nowrap}
.schedule-grid .freecell{background:rgba(19,58,43,.14)}
.duration-box{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.duration-metric{padding:10px;border:1px solid #20374a;border-radius:6px;background:#08131e}
.duration-metric small{display:block;color:#8198ab;font-size:9px}
.duration-metric strong{display:block;margin-top:3px;font-size:16px}
@media(max-width:1050px){.notice-layout{grid-template-columns:1fr}.notice-form .form-grid{grid-template-columns:1fr 1fr}}
@media(max-width:650px){.notice-form .form-grid,.duration-box{grid-template-columns:1fr}}


/* STUDENAC modul: praćenje dolazaka, overview i incidenti */
.performance-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px}
.performance-kpi{background:linear-gradient(180deg,#0e1c2b,#0a1520);border:1px solid #20364a;border-radius:8px;padding:14px}
.performance-kpi small{display:block;color:#8299ad;font-size:9px;font-weight:800;letter-spacing:.5px}
.performance-kpi strong{display:block;font-size:24px;margin-top:5px}
.performance-kpi span{color:#8fa4b6;font-size:9px}
.overview-layout{display:grid;grid-template-columns:1.15fr .85fr;gap:12px}
.data-wrap{overflow:auto}
.data-table{width:100%;border-collapse:collapse;min-width:850px}
.data-table th,.data-table td{padding:10px 9px;border-top:1px solid #1a2d3f;text-align:left;font-size:10px;vertical-align:middle}
.data-table th{font-size:9px;color:#8298aa;letter-spacing:.4px}
.data-table td{color:#dce8f0}
.score{display:inline-flex;align-items:center;gap:5px;font-weight:900}
.score.good{color:#37d879}.score.mid{color:#ffc04a}.score.bad{color:#ff5a62}
.delay-chip,.incident-chip{display:inline-flex;padding:3px 7px;border-radius:999px;font-size:9px;font-weight:900}
.delay-chip.good{color:#45df84;background:#0b3120;border:1px solid #17613a}
.delay-chip.late{color:#ff7278;background:#381319;border:1px solid #6b252b}
.delay-chip.early{color:#64b7ff;background:#0b2740;border:1px solid #164e7c}
.incident-chip{color:#ffb65d;background:#3b240e;border:1px solid #694215}
.mini-bars{padding:14px}
.supplier-bar{display:grid;grid-template-columns:minmax(160px,1fr) 2fr 52px;align-items:center;gap:10px;margin:9px 0}
.supplier-bar .name{font-size:9px;color:#cddae4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bar-track{height:8px;background:#15293b;border-radius:20px;overflow:hidden}
.bar-fill{height:100%;background:linear-gradient(90deg,#1673d1,#35d478);border-radius:20px}
.bar-score{text-align:right;font-size:10px;font-weight:900}
.incident-form{padding:15px;display:grid;gap:11px}
.incident-form .form-grid{grid-template-columns:1fr 1fr}
textarea{width:100%;min-height:85px;background:#07121d;color:#eaf2f8;border:1px solid #24394b;border-radius:5px;padding:10px;resize:vertical;font-family:inherit}
.arrival-modal{max-width:540px}
.arrival-summary{padding:11px;background:#081622;border:1px solid #20394e;border-radius:6px;color:#abc0d1;font-size:10px;line-height:1.6}
.arrival-summary strong{color:white}
.overview-empty{padding:28px;text-align:center;color:#71879a;font-size:11px}
@media(max-width:1050px){.performance-kpis{grid-template-columns:1fr 1fr}.overview-layout{grid-template-columns:1fr}}
@media(max-width:650px){.performance-kpis{grid-template-columns:1fr}.incident-form .form-grid{grid-template-columns:1fr}}


/* DOGRADNJE NA POSTOJEĆI STUDENAC YMS */
.workflow-wrap{display:flex;gap:4px;flex-wrap:wrap;min-width:620px}
.workflow-step{padding:4px 6px;border:1px solid #263b4d;border-radius:4px;font-size:7.5px;color:#72879a;background:#0a1520;font-weight:800}
.workflow-step.done{color:#48d780;border-color:#245f3e;background:#0b2519}
.workflow-step.current{color:#63b8ff;border-color:#285d8e;background:#0a2945}
.ops-kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:12px}
.ops-kpi{padding:13px;border:1px solid #20384b;border-radius:6px;background:#0a1622}
.ops-kpi small{display:block;font-size:8px;color:#8498aa;font-weight:800;letter-spacing:.5px}
.ops-kpi strong{display:block;font-size:22px;margin-top:4px}
.smart-note{margin-top:10px;padding:10px;border:1px solid #203d54;border-radius:5px;background:#081824;color:#a9bccb;font-size:10px;line-height:1.5}
.smart-note.good{border-color:#21633d;background:#092318}
.smart-note.warn{border-color:#75501c;background:#281c0c}
.alert-dynamic{display:grid;grid-template-columns:28px 1fr auto;gap:8px;align-items:center;padding:10px 12px;border-top:1px solid #1b2e40}
.alert-dynamic strong{font-size:10px}.alert-dynamic span{display:block;color:#a4b6c5;font-size:9px;margin-top:2px}.alert-dynamic time{font-size:8px;color:#71879a}
.alert-dynamic.danger b{color:#ff4b55}.alert-dynamic.warning b{color:#ff9c32}.alert-dynamic.info b{color:#3b99ff}
.oper-table{width:100%;border-collapse:collapse;min-width:1180px}
.oper-table th,.oper-table td{padding:9px;border-top:1px solid #1a2e40;text-align:left;font-size:9px;vertical-align:middle}
.oper-table th{font-size:8px;color:#8499ab}
.pro-planner-wrap{overflow:auto;padding:0 12px 14px}
.pro-schedule{min-width:1000px;display:grid;grid-template-columns:66px repeat(28,minmax(30px,1fr));grid-auto-rows:42px;border-left:1px solid #173047;border-top:1px solid #173047}
.pro-schedule>div{border-right:1px solid #173047;border-bottom:1px solid #173047;display:flex;align-items:center;justify-content:center;font-size:7.5px;overflow:hidden}
.pro-schedule .head{background:#0d1c2a;color:#a1b3c2}
.pro-schedule .ramp{background:#0d1c2a;color:#fff;font-weight:900}
.pro-schedule .freecell{background:rgba(18,60,42,.12)}
.pro-schedule .booked{margin:3px 2px;border-radius:4px;background:#115b9e;color:#fff;font-weight:900;padding:2px 4px;justify-content:flex-start;white-space:nowrap}
.pro-schedule .booked.waiting{background:#8a5819}.pro-schedule .booked.active{background:#19703d}.pro-schedule .booked.late{background:#8c2e36}
.incident-evidence{width:54px;height:40px;object-fit:cover;border-radius:4px;border:1px solid #29445b}
.photo-preview{display:flex;gap:8px;flex-wrap:wrap;margin-top:6px}
.photo-preview img{width:90px;height:68px;object-fit:cover;border-radius:5px;border:1px solid #29445b}
.report-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;padding:14px}
.report-stat{padding:12px;border:1px solid #21384c;border-radius:6px;background:#081521}
.report-stat small{font-size:8px;color:#8399ab;font-weight:800}.report-stat strong{display:block;margin-top:4px;font-size:20px}
.checkin-search{display:grid;grid-template-columns:2fr 1fr;gap:10px;padding:13px}
.modal-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}
