@media(max-width:600px){.warehouse-cards{grid-template-columns:1fr}}


/* CONTROL TOWER / CAPACITY / CALENDAR / HEATMAP */
.control-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.control-card{padding:12px;background:#0a1723;border:1px solid #20384c;border-radius:7px}
.control-card small{color:#7e94a7;font-size:8px;font-weight:900}.control-card strong{display:block;font-size:22px;margin-top:5px}
.capacitybar{height:8px;background:#07131f;border:1px solid #20384c;border-radius:99px;overflow:hidden;margin-top:7px}.capacitybar i{display:block;height:100%;background:#2a8cff}
.calendar-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:7px}.calday{min-height:105px;border:1px solid #20384c;background:#091723;border-radius:6px;padding:7px}.calday b{font-size:10px}.calitem{font-size:8px;margin-top:5px;padding:4px;background:#102c44;border-radius:4px}
.heat{display:grid;grid-template-columns:70px repeat(7,1fr);gap:3px}.heat div{padding:6px;text-align:center;font-size:8px;border-radius:3px;background:#0a1723}.heat .h1{background:#0d2537}.heat .h2{background:#123d58}.heat .h3{background:#19577a}.heat .h4{background:#236e93}
.blocked{border-color:#7d3c43!important;background:#32171b!important;color:#ff9ba0!important}
