/* POJEDNOSTAVLJEN UNOS NAJAVE */
#announcements{max-width:1500px;margin:0 auto}
.simple-ann-layout{display:grid;grid-template-columns:minmax(460px,640px) minmax(420px,1fr);gap:12px}
