.simple-ann-form .form-grid{grid-template-columns:1fr 1fr}
.simple-ann-form .full{grid-column:1/-1}
.ann-main-recommendation{margin-top:12px;border:1px solid #246caa;background:linear-gradient(180deg,#0b2843,#091d30);border-radius:8px;padding:16px}
.ann-main-recommendation.ready{border-color:#247544;background:linear-gradient(180deg,#0b2b1c,#091c15)}
.ann-main-recommendation.error{border-color:#8d333a;background:linear-gradient(180deg,#311319,#1c0d11)}
.ann-main-recommendation small{color:#7fa2bf;font-size:9px;font-weight:800}
.ann-main-recommendation h3{margin:5px 0 8px;font-size:20px}
.ann-recommend-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}
.ann-recommend-grid div{background:rgba(0,0,0,.13);border:1px solid rgba(255,255,255,.08);border-radius:6px;padding:10px}
.ann-recommend-grid small{display:block}.ann-recommend-grid strong{display:block;font-size:16px;margin-top:3px}
.ann-primary-action{width:100%;margin-top:12px;padding:12px;font-size:13px}
