.ann-advanced summary{cursor:pointer;color:#8fa9be;font-size:10px;font-weight:800}
.ann-advanced .form-grid{margin-top:10px}
.ann-help{font-size:9px;color:#8095a8;line-height:1.5;margin-top:7px}
#announcementSchedule{min-height:250px}
@media(max-width:1050px){.simple-ann-layout{grid-template-columns:1fr}}
@media(max-width:650px){.simple-ann-form .form-grid,.ann-recommend-grid{grid-template-columns:1fr}}


