.yms-toast{position:fixed;right:22px;top:82px;z-index:100000;min-width:300px;max-width:440px;padding:12px 14px;border-radius:8px;border:1px solid #2b4b61;background:#0b1926;color:#fff;box-shadow:0 18px 50px rgba(0,0,0,.45);display:none}
.yms-toast.show{display:block;animation:ymsToastIn .18s ease-out}
.yms-toast.success{border-color:#2c7b49;background:#0d2b1a;color:#9af0b3}
.yms-toast.error{border-color:#8b343b;background:#321317;color:#ff9fa5}
.yms-toast.info{border-color:#28679c;background:#0c2438;color:#94caff}
.yms-toast strong{display:block;color:#fff;font-size:11px;margin-bottom:3px}
.yms-toast span{font-size:9px;line-height:1.45}
@keyframes ymsToastIn{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:translateY(0)}}


#saveRecommendedAnnouncement.duplicate-flash{
  background:#9e2630!important;
