.yard-truck-icon{font-size:26px;line-height:1;margin-bottom:6px}
.yard-truck-plate{font-size:12px;font-weight:1000;color:#fff;letter-spacing:.4px}
.yard-truck-driver{font-size:8px;color:#ffd8b4;margin-top:3px}
.yard-truck-supplier{font-size:8px;color:#a9c2d3;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.yard-truck-time{font-size:7px;color:#ffae68;margin-top:5px;font-weight:900}
.yard-center-lane{border-left:2px dashed #6d7e87;border-right:2px dashed #6d7e87;position:relative;background:rgba(255,255,255,.015)}
.yard-lane-label{writing-mode:vertical-rl;transform:rotate(180deg);position:absolute;left:50%;top:50%;translate:-50% -50%;font-size:8px;color:#667f90;font-weight:950;letter-spacing:1px}
.yard-lane-markings{height:100%;background:repeating-linear-gradient(to bottom,transparent 0 26px,rgba(255,255,255,.14) 26px 42px,transparent 42px 68px);width:3px;margin:auto}
.yard-dock-preview{display:grid;gap:7px}.yard-dock-card{min-height:68px;border:1px solid #29485e;border-radius:6px;background:#071722;padding:8px}.yard-dock-card.occupied{border-color:#e8c238;background:#31290b}.yard-dock-card strong{display:block}.yard-dock-card small{display:block;color:#809caf;margin-top:3px}
.yard-current-list{display:grid;gap:7px}.yard-current-row{display:grid;grid-template-columns:120px 1.2fr 1fr 90px 130px 100px;gap:8px;align-items:center;padding:9px;border:1px solid #27445a;border-radius:6px;background:#081722;font-size:8px}.yard-current-row strong{color:#fff}.yard-current-row small{color:#819caf}
@media(max-width:900px){.yard-map-kpis{display:none}}


/* PORTA / CHECK-IN */
.gate-panel{border-color:#31566f!important}
.gate-body{padding:14px}
.gate-form{display:grid;grid-template-columns:1fr 1fr auto;gap:10px;align-items:end}
.gate-form label,.gate-override-box label{display:grid;gap:5px;color:#8ba7bb;font-size:8px;font-weight:950}
.gate-form input,.gate-override-box select{padding:11px 12px;border:1px solid #315169;border-radius:6px;background:#071724;color:#fff}
.gate-match-result{margin-top:12px;padding:11px 12px;border:1px solid #315169;border-radius:7px;background:#081724;display:flex;justify-content:space-between;gap:12px;align-items:center}
.gate-match-result strong{font-size:11px}.gate-match-result span{font-size:8px;color:#9ab2c3}
.gate-match-result.good{border-color:#2f8d57;background:#0b2b1a}.gate-match-result.good strong{color:#6fe39c}
.gate-match-result.bad{border-color:#9d3b45;background:#351419}.gate-match-result.bad strong{color:#ff8f98}
.gate-match-result.warn{border-color:#9a6a23;background:#33230d}.gate-match-result.warn strong{color:#ffc26c}
.gate-appointment-card{display:none;margin-top:10px;border:1px solid #29485e;border-radius:7px;background:#091a28;padding:12px}
.gate-appointment-card.show{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}
.gate-appointment-card div{padding:8px;border:1px solid #213a4d;border-radius:5px;background:#07151f}
.gate-appointment-card small{display:block;color:#7f9bad;font-size:7px;font-weight:950}.gate-appointment-card strong{display:block;margin-top:3px;font-size:10px}
.gate-entry-btn{width:100%;margin-top:10px;padding:13px;border:1px solid #2e9d5c;border-radius:6px;background:#15743a;color:#fff;font-size:11px;font-weight:1000;cursor:pointer}
.gate-entry-btn:disabled{opacity:.35;cursor:not-allowed;filter:saturate(.4)}
.gate-override-box{display:none;margin-top:10px;padding:10px;border:1px solid #8c5c1e;border-radius:7px;background:#2c1d0a;grid-template-columns:1fr auto;gap:8px;align-items:end}
.gate-override-box.show{display:grid}
.gate-override-btn{padding:10px;border:1px solid #bc7624;border-radius:6px;background:#6c3e0b;color:#fff;font-size:8px;font-weight:950;cursor:pointer}
@media(max-width:850px){.gate-form{grid-template-columns:1fr}.gate-appointment-card.show{grid-template-columns:repeat(2,1fr)}.gate-override-box.show{grid-template-columns:1fr}}


#checkinTable .gate-data-present{color:#7fe6a2!important}
#checkinTable .gate-data-missing{color:#ff9da4!important}


/* TABLICE / VOZAČ — JASNO VIDLJIVO U SVIM OPERATIVNIM PRIKAZIMA */
.identity-chip{
  display:inline-flex;align-items:center;gap:5px;
  padding:4px 8px;border-radius:999px;
  border:1px solid #2f7d4a;background:#0d2c1a;
  color:#8df0aa;font-size:8px;font-weight:950;white-space:nowrap;
}
.identity-missing{
  display:inline-flex;align-items:center;padding:4px 8px;border-radius:999px;
  border:1px solid #8c5a1f;background:#3a2610;color:#ffc36b;
  font-size:8px;font-weight:950;white-space:nowrap;
}
#checkinTable .gate-data-present{font-size:9px!important;color:#8df0aa!important}
.receiving-row .identity-chip,.yard-slot .identity-chip{margin-top:4px}


/* Jasna potvrda tablica/vozača nakon spremanja */
.driver-data-ok{font-size:8px!important;padding:4px 8px!important}


.home-storage-status{
  color:#7fdc9c;font-size:8px;font-weight:900;padding-bottom:9px;
}
.home-storage-status.warn{color:#ffc36b}


.driver-data-ok{
  color:#8df0aa!important;
  border-color:#2f8d57!important;
  background:#0b2b1a!important;
}


.yard-truck-pallets{
  display:inline-flex;
  margin-top:5px;
  padding:3px 6px;
  border-radius:999px;
  background:#16324a;
  border:1px solid #315b78;
  color:#b8dcf3;
  font-size:7px;
  font-weight:950;
}


/* RAMPE — LIVE PREGLED */
.dock-live-toolbar{
  display:flex;justify-content:space-between;align-items:center;gap:12px;
  padding:11px 13px;margin-bottom:12px;border:1px solid #29485e;
  background:#091924;border-radius:8px
}
.dock-live-toolbar strong{display:block;font-size:11px}
.dock-live-toolbar small{display:block;margin-top:3px;color:#7f9caf}
.dock-live-summary{display:flex;gap:8px}
.dock-live-summary span{
  padding:7px 10px;border:1px solid #29485e;background:#071724;border-radius:999px;
  font-size:8px;color:#a7bfce
}
.dock-live-summary b{color:#fff}
.dock-live-grid{display:grid;grid-template-columns:repeat(3,minmax(240px,1fr));gap:12px}
.dock-live-card{
  min-height:170px;border:1px solid #2b4a60;border-top:5px solid #456477;
  border-radius:9px;background:linear-gradient(180deg,#0a1a27,#07141e);
  padding:13px;transition:.16s ease
}
.dock-live-card:hover{transform:translateY(-2px);border-color:#3b6f91}
.dock-live-card.busy{
  border-top-color:#e8c238;
  background:linear-gradient(180deg,#32290b,#1c1808);
}
.dock-live-card.free{
  border-top-color:#2b8b55;
}
.dock-live-card h3{margin:0;font-size:14px}
.dock-live-free{
  height:110px;display:flex;flex-direction:column;align-items:center;justify-content:center;
  color:#77ca97;text-align:center;font-weight:950
}
.dock-live-free .icon{font-size:28px;margin-bottom:8px}
.dock-live-free small{color:#719486;font-size:8px}
.dock-live-truck{margin-top:10px;display:grid;gap:7px}
.dock-live-status{
  display:inline-flex;width:max-content;padding:4px 8px;border-radius:999px;
  border:1px solid #e8c238;color:#ffe17a;background:#4b3d09;
  font-size:7px;font-weight:950
}
.dock-live-identity{font-size:12px;font-weight:1000;color:#fff}
.dock-live-driver{font-size:9px;color:#e7d8a5}
.dock-live-supplier{font-size:9px;color:#c3d4df}
.dock-live-meta{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:4px}
.dock-live-meta div{padding:7px;border:1px solid #665a21;background:#211d09;border-radius:5px}
.dock-live-meta small{display:block;color:#a89c60;font-size:7px;font-weight:950}
.dock-live-meta strong{display:block;margin-top:2px;font-size:9px;color:#fff}
@media(max-width:1100px){.dock-live-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:700px){.dock-live-grid{grid-template-columns:1fr}}


/* KAMIONI — POVIJEST REGISTRACIJA */
.truck-history-toolbar{display:grid;grid-template-columns:1fr 210px;gap:9px;margin-bottom:12px}
.truck-history-toolbar input,.truck-history-toolbar select{padding:10px 11px;border:1px solid #29485e;border-radius:6px;background:#071724;color:#fff}
.truck-history-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-bottom:12px}
.truck-history-summary>div{padding:11px;border:1px solid #29485e;border-radius:7px;background:#091a27}
.truck-history-summary small{display:block;color:#7f9bad;font-size:7px;font-weight:950}.truck-history-summary strong{display:block;margin-top:3px;font-size:21px}
.truck-history-grid{display:grid;grid-template-columns:repeat(3,minmax(250px,1fr));gap:11px}
.truck-history-card{border:1px solid #29485e;border-radius:8px;background:linear-gradient(180deg,#0a1a27,#07141e);padding:12px;cursor:pointer;transition:.16s ease}
.truck-history-card:hover{transform:translateY(-2px);border-color:#2b8cff;box-shadow:0 10px 24px rgba(0,0,0,.2)}
.truck-history-card.returning{border-top:4px solid #2b8cff}
.truck-history-card.first{border-top:4px solid #6d8798}
.truck-history-head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}
.truck-history-plate{font-size:15px;font-weight:1000;letter-spacing:.6px;color:#fff}
.truck-return-badge{display:inline-flex;padding:4px 7px;border-radius:999px;border:1px solid #2b8cff;background:#0d2e4a;color:#88c6ff;font-size:7px;font-weight:950}
.truck-first-badge{display:inline-flex;padding:4px 7px;border-radius:999px;border:1px solid #60798b;background:#13212b;color:#a9bfcd;font-size:7px;font-weight:950}
.truck-history-main{margin-top:10px;display:grid;gap:5px}.truck-history-main span{font-size:8px;color:#a8becd}.truck-history-main strong{color:#fff}
.truck-history-meta{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:10px}
.truck-history-meta div{padding:7px;border:1px solid #213a4d;border-radius:5px;background:#07151f}
.truck-history-meta small{display:block;color:#718fa3;font-size:7px;font-weight:950}.truck-history-meta strong{display:block;margin-top:2px;font-size:9px}
.truck-history-visits{margin-top:10px;padding-top:9px;border-top:1px solid #20384b;display:grid;gap:5px}
.truck-history-visit{display:grid;grid-template-columns:90px 1fr 100px;gap:6px;font-size:7px;color:#8ea8ba}
.truck-history-empty{padding:40px;text-align:center;border:1px dashed #29485e;border-radius:8px;color:#718fa5}
@media(max-width:1100px){.truck-history-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:700px){.truck-history-grid{grid-template-columns:1fr}.truck-history-toolbar{grid-template-columns:1fr}}


/* DVORIŠTE — PSEUDO 3D + SMJERNICE PREMA RAMPI */
.yard-floorplan{
  perspective:1100px;
  background:
    radial-gradient(circle at 50% 0%,rgba(49,126,177,.12),transparent 35%),
    linear-gradient(180deg,#0a1a25,#06131b)!important;
}
.yard-layout{
  transform:rotateX(5deg);
  transform-origin:center top;
}
.yard-parking-zone,.yard-dock-zone{
  box-shadow:0 16px 35px rgba(0,0,0,.22), inset 0 1px 0 rgba(255,255,255,.025);
}
.yard-slot{
  box-shadow:0 8px 16px rgba(0,0,0,.16);
}
.yard-slot.occupied{
  box-shadow:0 12px 22px rgba(0,0,0,.26),0 0 0 1px rgba(255,139,34,.14);
}
.yard-truck-icon{
  display:inline-block;
  filter:drop-shadow(0 5px 4px rgba(0,0,0,.4));
}
.yard-route{
  display:flex;align-items:center;justify-content:space-between;gap:6px;
  margin-top:6px;padding:5px 7px;border-radius:5px;
  background:#10293b;border:1px solid #2f607e;
  color:#86ccff;font-size:7px;font-weight:950;
}
.yard-route-arrow{
  display:inline-block;
  font-size:13px;
  animation:yardArrowPulse 1s ease-in-out infinite;
}
@keyframes yardArrowPulse{
  0%,100%{transform:translateX(0);opacity:.65}
  50%{transform:translateX(5px);opacity:1}
}
.yard-slot.to-dock{
  animation:yardTruckLeaving .9s ease forwards;
  transform-origin:center;
}
@keyframes yardTruckLeaving{
  0%{transform:translate(0,0) scale(1);opacity:1}
  65%{transform:translate(45px,-10px) scale(.94);opacity:.8}
  100%{transform:translate(95px,-18px) scale(.82);opacity:0}
}
.yard-dock-card.busy{
  box-shadow:0 10px 24px rgba(232,194,56,.12);
}
.yard-dock-card .dock-truck-name{
  display:block;margin-top:5px;color:#fff;font-size:8px;font-weight:950;
}
.yard-dock-card .dock-truck-plate{
  display:block;margin-top:2px;color:#ffe17a;font-size:9px;font-weight:1000;
}
.yard-map-legend{
  display:flex;gap:10px;flex-wrap:wrap;margin:0 0 10px;
  color:#7f9bad;font-size:7px;font-weight:900;
}
.yard-map-legend span{display:inline-flex;align-items:center;gap:5px}
.yard-map-legend i{width:9px;height:9px;border-radius:3px;display:inline-block}


/* ===== YARDIVO IZOMETRIJSKO 3D DVORIŠTE ===== */
.yard-3d-scene{
  overflow:hidden!important;
  min-height:650px;
  border:1px solid #28485f!important;
  background:
    radial-gradient(circle at 50% 8%,rgba(70,145,194,.18),transparent 28%),
    linear-gradient(180deg,#0b1e2c 0%,#071620 55%,#051018 100%)!important;
  padding:16px!important;
  perspective:1400px!important;
}
.yard-3d-skyline{
  display:flex;justify-content:space-between;align-items:center;gap:12px;
  margin-bottom:14px;position:relative;z-index:10
}
.yard-3d-gate{
  padding:9px 14px;border-radius:6px;border:1px solid #338fe0;
  background:#0b2a41;color:#93ceff;font-size:8px;font-weight:1000;
  box-shadow:0 8px 22px rgba(0,0,0,.25)
}
.yard-3d-title{font-size:9px;font-weight:1000;color:#8ca9bb;letter-spacing:1px}
.yard-3d-world{
  position:relative;
  width:100%;
  min-height:540px;
  perspective:1500px;
}
.yard-3d-ground{
  position:relative;
  width:88%;
  min-height:470px;
  margin:30px auto 0;
  transform:rotateX(58deg) rotateZ(-18deg);
  transform-style:preserve-3d;
  transform-origin:center center;
  border:2px solid #344d58;
  border-radius:16px;
  background:
    linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px),
    #16232a;
  background-size:34px 34px;
  box-shadow:0 38px 75px rgba(0,0,0,.48),inset 0 0 45px rgba(0,0,0,.28);
}
.yard-3d-road{
  position:absolute;background:#232f34;border:1px solid #3b4c53;
  box-shadow:inset 0 0 0 3px rgba(255,255,255,.015)
}
.yard-3d-road::after{
  content:"";position:absolute;left:50%;top:0;bottom:0;width:2px;
  background:repeating-linear-gradient(to bottom,#d7bf66 0 14px,transparent 14px 29px);
}
.road-a{left:43%;top:5%;width:14%;height:91%}
.road-b{left:7%;top:42%;width:78%;height:12%}
.road-b::after{left:0;right:0;top:50%;bottom:auto;width:auto;height:2px;background:repeating-linear-gradient(to right,#d7bf66 0 14px,transparent 14px 29px)}
.road-c{right:13%;top:12%;width:12%;height:76%}

.yard-3d-parking{
  position:absolute;left:4%;top:7%;width:35%;height:82%;
  padding:10px;transform:translateZ(6px);transform-style:preserve-3d
}
.yard-3d-parking-grid{
  display:grid;grid-template-columns:repeat(4,1fr);gap:9px;
  height:calc(100% - 22px)
}
.yard-3d-parking-grid .yard-slot{
  min-height:72px!important;
  border:2px dashed #3b515b!important;
  background:#1b292f!important;
  transform-style:preserve-3d;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.018)!important;
}
.yard-3d-parking-grid .yard-slot.occupied{
  border-style:solid!important;
  border-color:#ff8b22!important;
  background:#2b2118!important;
}
.yard-3d-parking-grid .yard-slot.occupied .yard-truck-3d{
  transform:translateZ(26px) rotateX(-58deg) rotateZ(18deg);
}
.yard-empty-slot{font-size:6px!important}

/* 3D truck */
.yard-truck-3d{
  position:relative;width:58px;height:26px;margin:12px auto 5px;
  transform-style:preserve-3d;
  transition:transform .5s ease;
}
.truck-cab-3d{
  position:absolute;right:0;top:5px;width:19px;height:18px;border-radius:3px 4px 4px 2px;
  background:linear-gradient(145deg,#dfe8ed,#8ea5b2);
  border:1px solid #ebf4f7;box-shadow:5px 7px 10px rgba(0,0,0,.3)
}
.truck-cab-3d::before{
  content:"";position:absolute;left:3px;top:2px;width:10px;height:6px;
  background:#143044;border-radius:2px
}
.truck-box-3d{
  position:absolute;left:0;top:1px;width:40px;height:22px;border-radius:2px;
  background:linear-gradient(145deg,#f1f4f5,#9daeb7);
  border:1px solid #e8eff2;box-shadow:5px 7px 10px rgba(0,0,0,.3)
}
.truck-box-3d::after{
  content:"";position:absolute;left:5px;right:5px;top:7px;height:2px;background:#a5b5bd
}
.truck-wheel{
  position:absolute;width:8px;height:8px;border-radius:50%;background:#101416;
  border:2px solid #343d41;bottom:-5px
}
.truck-wheel.w1{left:8px}.truck-wheel.w2{right:6px}

.yard-truck-label-3d{
  transform:translateZ(29px) rotateX(-58deg) rotateZ(18deg);
  margin-top:1px;text-align:center;pointer-events:none
}
.yard-truck-label-3d strong{display:block;font-size:7px;color:#fff;white-space:nowrap}
.yard-truck-label-3d span{display:block;font-size:6px;color:#ffc990;white-space:nowrap;margin-top:1px}
.yard-truck-label-3d em{display:block;font-size:6px;color:#a9d7f2;font-style:normal;white-space:nowrap}

/* warehouse / docks */
.yard-3d-warehouse{
  position:absolute;right:1%;top:5%;width:23%;height:86%;
  transform:translateZ(18px);transform-style:preserve-3d
}
.warehouse-roof{
  height:17%;background:linear-gradient(145deg,#6f7c83,#424e55);
  border:1px solid #88959a;transform:translateZ(38px);
  display:flex;align-items:center;justify-content:center;
  color:#d8e1e5;font-size:8px;font-weight:1000
}
.warehouse-face{
  position:absolute;left:0;right:0;top:16%;bottom:0;
  background:linear-gradient(90deg,#5d696e,#3e4a50);
  border:1px solid #76858b;
  transform:translateZ(20px);
  padding:8px;
}
.yard-3d-docks{display:grid;gap:7px;height:100%}
.yard-3d-docks .yard-dock-card{
  min-height:0!important;display:flex;flex-direction:column;justify-content:center;
  border:2px solid #252f33!important;background:#1b2327!important;
  box-shadow:inset 0 -8px 0 rgba(0,0,0,.22)!important
}
.yard-3d-docks .yard-dock-card.occupied{
  border-color:#e8c238!important;background:#40360e!important;
}
.yard-3d-docks .yard-dock-card strong{font-size:7px!important}
.yard-3d-docks .dock-truck-name{font-size:6px!important}
.yard-3d-docks .dock-truck-plate{font-size:7px!important}

/* green guidance routes */
.yard-3d-routes{position:absolute;inset:0;pointer-events:none;transform:translateZ(12px)}
.yard-route-line{
  position:absolute;height:5px;border-radius:999px;
  background:#37e36d;
  box-shadow:0 0 10px rgba(55,227,109,.75),0 0 22px rgba(55,227,109,.3);
  transform-origin:left center;
}
.yard-route-line::after{
  content:"";position:absolute;right:-8px;top:-5px;
  border-left:12px solid #37e36d;border-top:7px solid transparent;border-bottom:7px solid transparent;
  filter:drop-shadow(0 0 5px rgba(55,227,109,.7));
}
.yard-route-line::before{
  content:"";position:absolute;inset:0;
  background:linear-gradient(90deg,transparent 0 35%,rgba(255,255,255,.9) 50%,transparent 65%);
  animation:routeFlow 1.2s linear infinite;
}
@keyframes routeFlow{from{transform:translateX(-55%)}to{transform:translateX(115%)}}

.yard-3d-legend{
  display:flex;gap:12px;flex-wrap:wrap;justify-content:center;margin-top:6px;
  color:#819cad;font-size:7px;font-weight:900
}
.yard-3d-legend span{display:inline-flex;align-items:center;gap:5px}
.yard-3d-legend i{width:9px;height:9px;border-radius:3px}
.truck-dot{background:#ff8b22}.route-dot{background:#37e36d}.dock-dot{background:#e8c238}

@media(max-width:900px){
  .yard-3d-scene{min-height:560px}
  .yard-3d-world{min-height:440px}
  .yard-3d-ground{width:96%;min-height:390px}
}


/* KRITIČNI LAYOUT FIX — samo aktivna sekcija smije zauzimati prostor */
.view{display:none!important}
.view.active{display:block!important}

/* Sekcije koje su povijesno završile izvan <main> poravnaj u isti app content viewport */
body:not(.home-menu-mode) body>.view.active,
body:not(.home-menu-mode) .app-shell~.view.active,
body:not(.home-menu-mode) .app~.view.active{
  margin-left:252px!important;
  width:calc(100% - 252px)!important;
  min-height:calc(100vh - 64px)!important;
  padding:22px!important;
  box-sizing:border-box!important;
}

/* Glavni sadržaj uvijek počinje odmah ispod topbara */
body:not(.home-menu-mode) .main>.view.active{
  margin-top:0!important;
  padding-top:22px!important;
}


body:not(.home-menu-mode)>section.view.active{
  position:absolute!important;
  top:64px!important;
  left:252px!important;
  right:0!important;
  width:auto!important;
  margin:0!important;
  padding:22px!important;
  z-index:5!important;
  background:var(--bg,#050b12)!important;
}


/* ===== DVORIŠTE PREMA SATELITSKOM RASPOREDU ===== */
.satellite-yard-scene{
  min-height:650px!important;
  overflow:hidden!important;
  padding:14px!important;
  border:1px solid #2a4c62!important;
  border-radius:10px!important;
  background:
    radial-gradient(circle at 20% 0%,rgba(57,126,174,.14),transparent 26%),
    linear-gradient(180deg,#0a1c29,#06131c)!important;
  perspective:1500px!important;
}
.sat-yard-header{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px}
.sat-yard-gate{padding:9px 14px;border:1px solid #2488dc;border-radius:6px;background:#092941;color:#8fd0ff;font-size:8px;font-weight:1000}
.sat-yard-title{font-size:8px;letter-spacing:1px;color:#849eaf;font-weight:1000}
.sat-yard-world{position:relative;min-height:540px;perspective:1500px}
.sat-yard-ground{
  position:relative;
  width:93%;
  height:440px;
  margin:40px auto 0;
  transform:rotateX(57deg) rotateZ(-11deg);
  transform-style:preserve-3d;
  transform-origin:center;
  border:2px solid #385462;
  border-radius:14px;
  background:
    linear-gradient(rgba(255,255,255,.022) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.022) 1px,transparent 1px),
    #1a282f;
  background-size:30px 30px;
  box-shadow:0 42px 80px rgba(0,0,0,.5),inset 0 0 50px rgba(0,0,0,.28);
}
.sat-yard-construction{
  position:absolute;left:0;top:0;width:100%;height:13%;
  background:linear-gradient(90deg,#2a2d28,#31342d 45%,#252925);
  opacity:.9;border-bottom:1px solid #4d534d;
}
.sat-yard-parking-strip{
  position:absolute;left:3%;top:15%;width:62%;height:31%;
  transform:translateZ(7px);transform-style:preserve-3d
}
.sat-yard-parking-label{font-size:7px;color:#9aafbc;font-weight:1000;margin-bottom:4px}
.sat-yard-parking-grid{
  height:calc(100% - 18px);
  display:grid;
  grid-template-columns:repeat(16,1fr);
  gap:3px;
}
.sat-yard-parking-grid .yard-slot{
  min-height:0!important;
  border:1px solid #778b95!important;
  border-left:2px solid #c4d0d5!important;
  border-right:0!important;
  border-radius:0!important;
  background:#222f35!important;
  padding:2px!important;
  overflow:visible!important;
  position:relative;
  transform-style:preserve-3d;
}
.sat-yard-parking-grid .yard-slot:last-child{border-right:2px solid #c4d0d5!important}
.sat-yard-parking-grid .yard-slot.occupied{
  background:#2d271c!important;
  border-color:#ff9a3d!important;
  box-shadow:inset 0 0 0 1px rgba(255,154,61,.25)!important;
}
.sat-yard-parking-grid .yard-slot-id{
  top:-13px!important;right:1px!important;font-size:5px!important;color:#8197a5!important
}
.sat-yard-parking-grid .yard-empty-slot{
  font-size:5px!important;color:#596d78!important;transform:rotate(90deg)
}
.sat-yard-drive-lane{
  position:absolute;left:2%;top:48%;width:88%;height:23%;
  border-top:1px solid #4a585e;border-bottom:1px solid #4a585e;
  background:#252f34;
}
.sat-yard-centerline{
  position:absolute;left:0;right:0;top:50%;height:2px;
  background:repeating-linear-gradient(to right,#e4c84e 0 18px,transparent 18px 38px)
}
.sat-yard-entry-arrow{
  position:absolute;left:4%;top:17%;color:#4fe77c;font-size:24px;font-weight:1000;
  filter:drop-shadow(0 0 5px rgba(79,231,124,.65))
}

/* Warehouse like long edge of the real building */
.sat-yard-warehouse{
  position:absolute;right:1.5%;top:12%;width:27%;height:77%;
  transform:translateZ(20px);transform-style:preserve-3d
}
.sat-yard-roof{
  height:16%;
  background:linear-gradient(145deg,#d6d8d4,#8e999b);
  border:1px solid #eef1ee;
  transform:translateZ(34px);
  display:flex;align-items:center;justify-content:center;
  color:#23343d;font-size:8px;font-weight:1000;
  box-shadow:8px 12px 18px rgba(0,0,0,.25)
}
.sat-yard-wall{
  position:absolute;left:0;right:0;top:15%;bottom:0;
  padding:7px;
  border:1px solid #77878c;
  background:linear-gradient(90deg,#5f6d72,#3f4b50);
  transform:translateZ(18px);
}
.sat-yard-docks{display:grid;grid-template-rows:repeat(6,1fr);gap:5px;height:100%}
.sat-yard-docks .yard-dock-card{
  min-height:0!important;
  display:flex;flex-direction:column;justify-content:center;
  padding:5px!important;border:2px solid #252d31!important;
  border-radius:2px!important;background:#1a2226!important;
  box-shadow:inset 0 -7px 0 rgba(0,0,0,.25)!important
}
.sat-yard-docks .yard-dock-card.occupied{
  background:#3c330e!important;border-color:#e5c334!important
}
.sat-yard-docks .yard-dock-card strong{font-size:6px!important}
.sat-yard-docks .dock-truck-name{font-size:5px!important}
.sat-yard-docks .dock-truck-plate{font-size:6px!important}

/* Proper 3D semi-truck: cab + long trailer */
.sleper-3d{
  position:absolute;
  left:50%;top:50%;
  width:95px;height:24px;
  transform:translate(-50%,-50%) translateZ(30px) rotateX(-57deg) rotateZ(11deg) rotate(90deg);
  transform-style:preserve-3d;
  pointer-events:none;
  filter:drop-shadow(8px 10px 6px rgba(0,0,0,.35));
}
.sleper-trailer{
  position:absolute;left:0;top:2px;width:70px;height:20px;border-radius:2px;
  background:linear-gradient(145deg,#f5f7f8,#9baab1);
  border:1px solid #eef4f6;
  box-shadow:inset -7px -5px 0 rgba(0,0,0,.08)
}
.sleper-trailer::before{
  content:"";position:absolute;left:6px;right:6px;top:4px;height:2px;background:#b8c4ca
}
.sleper-cab{
  position:absolute;right:1px;top:1px;width:23px;height:22px;border-radius:4px 6px 5px 3px;
  background:linear-gradient(145deg,#dde7eb,#7d96a3);
  border:1px solid #eef5f8
}
.sleper-cab::before{
  content:"";position:absolute;left:3px;top:3px;width:14px;height:7px;border-radius:2px;background:#153346
}
.sleper-cab::after{
  content:"";position:absolute;right:-2px;top:14px;width:5px;height:5px;border-radius:1px;background:#d3dadd
}
.sleper-wheel{
  position:absolute;bottom:-5px;width:8px;height:8px;border-radius:50%;background:#0d1113;border:2px solid #374247
}
.sleper-wheel.w1{left:12px}.sleper-wheel.w2{left:54px}.sleper-wheel.w3{right:4px}

.sleper-label{
  position:absolute;
  left:50%;top:102%;
  min-width:120px;
  transform:translateX(-50%) translateZ(34px) rotateX(-57deg) rotateZ(11deg);
  text-align:center;pointer-events:none
}
.sleper-label strong{display:block;color:#fff;font-size:7px;white-space:nowrap}
.sleper-label span{display:block;color:#ffd19a;font-size:6px;white-space:nowrap;margin-top:1px}
.sleper-label em{display:block;color:#7df5a1;font-size:6px;font-style:normal;font-weight:1000;white-space:nowrap;margin-top:2px}

/* green animated route from each lorry to its assigned dock */
.sat-yard-route-layer{position:absolute;inset:0;pointer-events:none;transform:translateZ(16px)}
.sat-yard-route{
  position:absolute;height:6px;border-radius:999px;background:#41e876;
  box-shadow:0 0 8px rgba(65,232,118,.9),0 0 20px rgba(65,232,118,.4);
  transform-origin:left center;
  overflow:visible
}
.sat-yard-route::after{
  content:"";position:absolute;right:-10px;top:-6px;
  border-left:14px solid #41e876;border-top:9px solid transparent;border-bottom:9px solid transparent;
  filter:drop-shadow(0 0 5px rgba(65,232,118,.85))
}
.sat-yard-route::before{
  content:"";position:absolute;inset:0;
  background:linear-gradient(90deg,transparent 0 30%,#eaffef 50%,transparent 70%);
  animation:satRouteFlow 1.05s linear infinite
}
@keyframes satRouteFlow{from{transform:translateX(-60%)}to{transform:translateX(120%)}}

.yard-3d-legend{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;margin-top:4px;color:#839ba9;font-size:7px;font-weight:900}
.yard-3d-legend span{display:inline-flex;align-items:center;gap:5px}.yard-3d-legend i{width:9px;height:9px;border-radius:3px}
.truck-dot{background:#ff9a3d}.route-dot{background:#41e876}.dock-dot{background:#e5c334}

@media(max-width:1000px){
  .satellite-yard-scene{min-height:570px!important}
  .sat-yard-world{min-height:460px}
  .sat-yard-ground{width:98%;height:380px}
}


