.live3d-mainroad{position:absolute;left:3%;top:47%;width:88%;height:22%;background:#202a2f;border-top:1px solid #39484f;border-bottom:1px solid #39484f}
.road-dash{position:absolute;left:0;right:0;top:50%;height:2px;background:repeating-linear-gradient(90deg,#9a7e28 0 17px,transparent 17px 36px)}
.live3d-building{position:absolute;right:1%;top:5%;width:29%;height:87%;transform:translateZ(24px);transform-style:preserve-3d}
.building-roof{height:19%;background:linear-gradient(145deg,#293a47,#101c25);border:1px solid #405564;transform:translateZ(42px);box-shadow:10px 14px 25px rgba(0,0,0,.4);display:flex;align-items:center;justify-content:center}.building-roof span{font-size:7px;color:#7f96a4;font-weight:1000}
