/* More realistic articulated semi-truck built in CSS */
.live-semi{position:absolute;left:50%;top:50%;width:112px;height:29px;transform:translate(-50%,-50%) translateZ(35px) rotateX(-58deg) rotateZ(12deg);transform-style:preserve-3d;filter:drop-shadow(8px 10px 7px rgba(0,0,0,.55));pointer-events:none}
.live-trailer{position:absolute;left:0;top:2px;width:82px;height:25px;border-radius:2px;background:linear-gradient(160deg,#f6f7f7 0%,#d4dade 52%,#8c9ba3 100%);border:1px solid #fff;box-shadow:inset -8px -5px 0 rgba(0,0,0,.09)}
.live-trailer::after{content:"";position:absolute;left:5px;right:5px;bottom:4px;height:2px;background:#8f9ca2;box-shadow:0 -4px 0 #c3ccd0}
.live-cab{position:absolute;right:0;top:0;width:31px;height:29px;border-radius:7px 8px 5px 4px;background:linear-gradient(150deg,#f2f5f5,#9aabb3);border:1px solid #eef5f7}
.live-cab::before{content:"";position:absolute;left:5px;top:3px;width:18px;height:9px;border-radius:3px;background:linear-gradient(#29424f,#0f2029)}
.live-cab::after{content:"";position:absolute;right:-2px;top:18px;width:6px;height:5px;background:#d9e0e2;border-radius:1px}
.live-wheel{position:absolute;bottom:-5px;width:9px;height:9px;border-radius:50%;background:#080b0d;border:2px solid #3b4448}.live-wheel.a{left:13px}.live-wheel.b{left:61px}.live-wheel.c{right:5px}
.live-semi-label{position:absolute;left:50%;bottom:103%;min-width:126px;transform:translateX(-50%) translateZ(42px) rotateX(-58deg) rotateZ(12deg);padding:6px 8px;border:1px solid #173827;border-radius:5px;background:rgba(4,12,16,.94);box-shadow:0 8px 20px rgba(0,0,0,.35);text-align:left;pointer-events:none}
