/* neon green route */
.live3d-routes{position:absolute;inset:0;pointer-events:none;transform:translateZ(18px)}
.neon-route{position:absolute;height:5px;border-radius:999px;background:#57ff29;box-shadow:0 0 6px #57ff29,0 0 15px #43ff18,0 0 30px rgba(65,255,25,.42);transform-origin:left center}
.neon-route::after{content:"";position:absolute;right:-11px;top:-7px;border-left:16px solid #57ff29;border-top:9px solid transparent;border-bottom:9px solid transparent;filter:drop-shadow(0 0 7px #45ff1e)}
.neon-route::before{content:"";position:absolute;inset:-1px;background:linear-gradient(90deg,transparent 0 25%,#efffe9 48%,transparent 68%);animation:neonFlow .85s linear infinite}
@keyframes neonFlow{from{transform:translateX(-55%)}to{transform:translateX(125%)}}

/* truck physically docked into ramp */
.docked-semi{position:absolute;left:-62px;top:50%;width:70px;height:18px;transform:translateY(-50%);z-index:3;filter:drop-shadow(4px 5px 4px rgba(0,0,0,.5))}
.docked-semi .ds-trailer{position:absolute;left:0;top:1px;width:52px;height:16px;background:linear-gradient(150deg,#eef2f3,#8d9da5);border:1px solid #eaf0f2}
.docked-semi .ds-cab{position:absolute;right:0;top:0;width:20px;height:18px;border-radius:4px;background:linear-gradient(145deg,#e5ebed,#81959f);border:1px solid #eaf1f3}
.docked-semi .ds-cab::before{content:"";position:absolute;left:3px;top:2px;width:11px;height:5px;background:#18303d;border-radius:1px}

.live3d-ramp-panel{position:absolute;right:0;top:0;width:260px;z-index:40;padding:11px;border:1px solid #183344;border-radius:7px;background:rgba(4,12,18,.95);box-shadow:0 16px 40px rgba(0,0,0,.5)}
.ramp-panel-title{font-size:8px;color:#fff;font-weight:1000;margin-bottom:8px}
.ramp-state-row{display:grid;grid-template-columns:48px 1fr auto;gap:6px;align-items:center;padding:7px 2px;border-top:1px solid #122734;font-size:6px;color:#8ba1ae}.ramp-state-row b{color:#dce6ea}.ramp-state-row .free{color:#5d8198}.ramp-state-row .busy{color:#6dff46;font-weight:1000}.ramp-state-row small{font-size:5px;color:#8299a7}
.live3d-legend{display:flex;gap:13px;flex-wrap:wrap;justify-content:center;margin-top:3px;font-size:7px;color:#748d9c;font-weight:900}.live3d-legend span{display:flex;align-items:center;gap:5px}.live3d-legend i{width:10px;height:7px;border-radius:2px}.lg-yard{background:#65ff39}.lg-route{height:2px!important;background:#65ff39;box-shadow:0 0 5px #65ff39}.lg-free{border:1px solid #3e7598;background:#10202a}.lg-busy{background:#65ff39}


