/* Floor lane: thick neon strip, not a thin line */
.neon-route{
  height:16px!important;
  border-radius:4px!important;
  background:
    linear-gradient(180deg,rgba(161,255,126,.95),rgba(70,255,34,.85) 45%,rgba(24,179,16,.9))!important;
