/* ===== PRAVA CSS 3D MAKETA DVORIŠTA ===== */
#yard3DGround{transform-style:preserve-3d!important}

/* 3D skladište: 5 vidljivih ploha */
.warehouse-cuboid{
  --wh-w:360px;--wh-h:300px;--wh-d:100px;
  position:absolute!important;right:2%!important;top:7%!important;
  width:var(--wh-w)!important;height:var(--wh-h)!important;
  transform:translateZ(54px)!important;transform-style:preserve-3d!important;
}
.warehouse-face{position:absolute;box-sizing:border-box;border:1px solid #65747a;backface-visibility:visible}
.wh-front{left:0;top:0;width:var(--wh-w);height:var(--wh-h);transform:translateZ(50px);background:linear-gradient(180deg,#5d696e,#364248);padding:12px;box-shadow:0 14px 28px rgba(0,0,0,.34)}
.wh-back{left:0;top:0;width:var(--wh-w);height:var(--wh-h);transform:rotateY(180deg) translateZ(50px);background:#2b363b}
.wh-left,.wh-right{top:0;width:100px;height:var(--wh-h);background:linear-gradient(90deg,#48545a,#2d383d)}
.wh-left{left:-50px;transform:rotateY(-90deg)}
.wh-right{right:-50px;transform:rotateY(90deg)}
.wh-top{left:0;top:-50px;width:var(--wh-w);height:100px;transform:rotateX(90deg);background:linear-gradient(180deg,#849095,#515e63);display:flex;align-items:center;justify-content:center;color:#e0e7ea;font-size:8px;font-weight:1000;letter-spacing:.8px}

/* 3D rampe - sivi kvadri oko crnog otvora */
.live3d-docks{display:grid!important;grid-template-rows:repeat(6,1fr)!important;gap:8px!important;height:100%!important}
.live3d-docks .yard-dock-card{position:relative!important;min-height:0!important;border:0!important;background:transparent!important;box-shadow:none!important;padding:4px 8px 4px 60px!important;overflow:visible!important;transform-style:preserve-3d!important}
.ramp3d{--rw:50px;--rh:35px;--rd:22px;position:absolute;left:4px;top:50%;width:var(--rw);height:var(--rh);transform:translateY(-50%) translateZ(18px);transform-style:preserve-3d}
.ramp3d-face{position:absolute;box-sizing:border-box;backface-visibility:visible}
.r3-front{width:var(--rw);height:var(--rh);transform:translateZ(11px);background:#070a0c;border:6px solid #59666c;box-shadow:inset 0 0 15px #000}
.r3-back{width:var(--rw);height:var(--rh);transform:rotateY(180deg) translateZ(11px);background:#263136}
.r3-left,.r3-right{width:22px;height:var(--rh);background:#69767b}
.r3-left{left:-11px;transform:rotateY(-90deg)}
.r3-right{right:-11px;transform:rotateY(90deg)}
.r3-top{width:var(--rw);height:22px;top:-11px;transform:rotateX(90deg);background:#7b878c}
.ramp-led{position:absolute;right:-3px;top:50%;width:4px;height:17px;transform:translateY(-50%) translateZ(15px);border-radius:2px;background:#4fff49;box-shadow:0 0 8px #4fff49}
.yard-dock-card.occupied .r3-front{border-color:#ff3d3d;box-shadow:0 0 14px rgba(255,50,50,.65),inset 0 0 15px #000}
.yard-dock-card.occupied .ramp-led{background:#ff3d3d;box-shadow:0 0 9px #ff3d3d}

/* Bijeli 3D šleper: odvojena prikolica i kabina, svaka kao kvadar */
.semi3d{position:absolute;left:50%;top:50%;width:116px;height:34px;transform:translate(-50%,-50%) translateZ(48px);transform-style:preserve-3d;pointer-events:none}
.trailer3d,.cab3d{position:absolute;transform-style:preserve-3d}
.trailer3d{left:0;top:3px;width:80px;height:28px}
.cab3d{left:80px;top:1px;width:31px;height:31px}
.box-face{position:absolute;box-sizing:border-box;border:1px solid #dce3e6;backface-visibility:visible}
.trailer3d .bf-front,.trailer3d .bf-back{width:80px;height:28px}
.trailer3d .bf-front{transform:translateZ(13px);background:linear-gradient(145deg,#fff,#dce3e6)}
.trailer3d .bf-back{transform:rotateY(180deg) translateZ(13px);background:#aebbc0}
.trailer3d .bf-top,.trailer3d .bf-bottom{width:80px;height:26px;top:1px}
.trailer3d .bf-top{transform:rotateX(90deg);background:#f8fbfc}
.trailer3d .bf-bottom{transform:rotateX(-90deg);background:#929fa5}
.trailer3d .bf-left,.trailer3d .bf-right{width:26px;height:28px;background:#c1ccd0}
.trailer3d .bf-left{left:-13px;transform:rotateY(-90deg)}
.trailer3d .bf-right{right:-13px;transform:rotateY(90deg)}
.cab3d .bf-front,.cab3d .bf-back{width:31px;height:31px}
.cab3d .bf-front{transform:translateZ(13px);background:linear-gradient(145deg,#fafcfc,#b9c6cb);border-radius:4px}
.cab3d .bf-back{transform:rotateY(180deg) translateZ(13px);background:#93a4ab}
.cab3d .bf-top,.cab3d .bf-bottom{width:31px;height:26px;top:2px}
.cab3d .bf-top{transform:rotateX(90deg);background:#f5f8f9}
.cab3d .bf-bottom{transform:rotateX(-90deg);background:#81939b}
.cab3d .bf-left,.cab3d .bf-right{width:26px;height:31px;background:#bec9cd}
.cab3d .bf-left{left:-13px;transform:rotateY(-90deg)}
.cab3d .bf-right{right:-13px;transform:rotateY(90deg)}
.cab-window{position:absolute;left:7px;top:5px;width:16px;height:8px;transform:translateZ(14px);background:#1d3643;border-radius:2px;z-index:5}
.wheel3d{position:absolute;width:10px;height:10px;border-radius:50%;background:#080a0b;border:2px solid #3e484c;transform:rotateX(90deg) translateZ(-8px)}
.wheel3d.w1{left:13px;top:25px}.wheel3d.w2{left:66px;top:25px}.wheel3d.w3{left:94px;top:25px}

/* Šleper koji je fizički priključen na rampu */
