/* ===== OVERVIEW GLAVNI GRAF SVIH DOBAVLJAČA ===== */
.overview-main-chart{margin-bottom:12px}
.overview-chart-legend{display:flex;gap:10px;flex-wrap:wrap;font-size:6px;color:#809bad;font-weight:900}
.overview-chart-legend span{display:inline-flex;align-items:center;gap:5px}
.overview-chart-legend i{width:9px;height:9px;border-radius:2px}
.overview-chart-legend i.good{background:#4fd27a}.overview-chart-legend i.mid{background:#e1b547}.overview-chart-legend i.bad{background:#e55c68}
.overview-supplier-chart{
  min-height:255px;
  padding:14px 12px 10px;
  display:flex;
  align-items:flex-end;
  gap:5px;
  overflow-x:auto;
  border-top:1px solid #1d3749;
  background:
    linear-gradient(to top,rgba(255,255,255,.025) 1px,transparent 1px);
  background-size:100% 25%;
}
.overview-chart-col{
  flex:1 0 34px;
  min-width:34px;
  max-width:70px;
  height:220px;
  display:flex;
  flex-direction:column;
  justify-content:flex-end;
  align-items:center;
  gap:5px;
  cursor:pointer;
}
.overview-chart-value{font-size:6px;font-weight:1000;color:#dce7ed}
.overview-chart-bar-wrap{
  width:72%;
  height:160px;
  display:flex;
  align-items:flex-end;
  border-bottom:1px solid #355064;
}
.overview-chart-bar{
  width:100%;
  min-height:3px;
  border-radius:4px 4px 1px 1px;
  transition:.18s ease;
}
.overview-chart-bar.good{background:linear-gradient(180deg,#6eea93,#2d9e5a)}
.overview-chart-bar.mid{background:linear-gradient(180deg,#f3d36f,#b58121)}
.overview-chart-bar.bad{background:linear-gradient(180deg,#f27c87,#a93240)}
.overview-chart-col:hover .overview-chart-bar{filter:brightness(1.18);transform:scaleX(1.08)}
.overview-chart-name{
  width:100%;
  min-height:42px;
  font-size:5px;
  line-height:1.25;
  color:#8098a8;
  text-align:center;
  overflow:hidden;
  display:-webkit-box;
  -webkit-line-clamp:3;
  -webkit-box-orient:vertical;
}
.overview-chart-empty{width:100%;padding:60px 10px;text-align:center;color:#718c9e;font-size:8px}


/* ===== CLEAN / EXECUTIVE DASHBOARD ===== */
.dash-clean-title{margin-bottom:12px}
.dash-clean-kpis{
  display:grid;
  grid-template-columns:repeat(6,minmax(120px,1fr));
  gap:9px;
  margin-bottom:12px;
}
.dash-clean-kpi{
  position:relative;
  padding:13px 12px;
  border:1px solid #244457;
  border-radius:8px;
  background:linear-gradient(145deg,#0a1a26,#07141d);
  overflow:hidden;
}
.dash-clean-kpi::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:#476679}
.dash-clean-kpi.green::before{background:#36b76a}.dash-clean-kpi.yellow::before{background:#dfb240}.dash-clean-kpi.orange::before{background:#da7a2d}.dash-clean-kpi.red::before{background:#df4a57}.dash-clean-kpi.blue::before{background:#3c8dd8}
.dash-clean-kpi small{display:block;font-size:6px;color:#7895a8;font-weight:1000}
.dash-clean-kpi strong{display:block;margin-top:4px;font-size:22px;color:#fff}
.dash-clean-kpi span{display:block;margin-top:2px;font-size:6px;color:#7892a3}
.dash-kpi-value-row{display:flex;align-items:flex-end;justify-content:space-between;gap:8px;margin-top:4px}
.dash-kpi-value-row strong{margin-top:0!important}
.dash-vs-yesterday{display:inline-flex!important;align-items:center;gap:3px;margin:0 0 3px!important;padding:3px 5px;border-radius:999px;border:1px solid #355064;font-size:6px!important;font-weight:1000;white-space:nowrap}
.dash-vs-yesterday.up{color:#7ce39b!important;border-color:#2f7650;background:#0c2a1b}
.dash-vs-yesterday.down{color:#ff939b!important;border-color:#7f3540;background:#301219}
.dash-vs-yesterday.same{color:#a9bdca!important;border-color:#405b6d;background:#0c1c27}
.dash-vs-yesterday.new{color:#77bfff!important;border-color:#2d6590;background:#0b2235}
.dash-vs-yesterday.closed{color:#ff818b!important;border-color:#943743;background:#351118}
.dash-vs-yesterday .x{font-size:8px;line-height:1}
.dash-kpi-yesterday-note{margin-top:4px!important;font-size:6px!important;color:#6f899b!important}
.dash-clean-grid{
  display:grid;
  grid-template-columns:1.1fr 1.45fr .9fr;
  gap:11px;
  margin-bottom:11px;
}
.dash-chart-panel{min-height:275px}
.dash-donut-wrap{display:grid;grid-template-columns:155px 1fr;gap:12px;align-items:center;padding:14px}
.dash-donut{
  width:145px;height:145px;border-radius:50%;
  position:relative;
  display:grid;place-items:center;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.03)
}
.dash-donut::after{
  content:"";position:absolute;width:84px;height:84px;border-radius:50%;
  background:#07141d;border:1px solid #1f3a4b
}
.dash-donut-center{position:relative;z-index:2;text-align:center}
.dash-donut-center strong{display:block;font-size:24px}.dash-donut-center small{display:block;font-size:6px;color:#7691a4}
.dash-donut-legend{display:grid;gap:7px}
.dash-donut-row{display:grid;grid-template-columns:8px 1fr auto;gap:7px;align-items:center;font-size:7px;color:#9bb0bd}
.dash-donut-row i{width:8px;height:8px;border-radius:2px}.dash-donut-row strong{color:#fff}
.dash-hourly-chart{height:220px;padding:16px 12px 12px;display:flex;align-items:flex-end;gap:6px;border-top:1px solid #1b3344}
.dash-hour-col{flex:1;min-width:18px;height:190px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:5px}
.dash-hour-value{font-size:6px;color:#dce7ed;font-weight:1000}
.dash-hour-track{height:145px;width:62%;display:flex;align-items:flex-end;border-bottom:1px solid #345064}
.dash-hour-bar{width:100%;min-height:2px;border-radius:3px 3px 0 0;background:linear-gradient(180deg,#4aa8ed,#23689d)}
.dash-hour-label{font-size:5px;color:#728d9f}
.dash-capacity-simple{padding:16px}
.dash-cap-ring{
  width:150px;height:150px;border-radius:50%;margin:2px auto 13px;
  display:grid;place-items:center;position:relative
}
.dash-cap-ring::after{content:"";position:absolute;width:96px;height:96px;border-radius:50%;background:#07141d;border:1px solid #1f3a4b}
.dash-cap-ring .inner{position:relative;z-index:2;text-align:center}.dash-cap-ring strong{display:block;font-size:24px}.dash-cap-ring small{font-size:6px;color:#7894a7}
.dash-cap-metrics{display:grid;grid-template-columns:1fr 1fr;gap:7px}
.dash-cap-metrics div{padding:8px;border:1px solid #203b4d;border-radius:5px;background:#071722}.dash-cap-metrics small{display:block;font-size:6px;color:#7591a5}.dash-cap-metrics strong{display:block;margin-top:3px;font-size:11px}
.dash-bottom-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:11px}
.dash-attention-count{min-width:25px;text-align:center;padding:5px 7px;border:1px solid #9a3a46;border-radius:999px;background:#351217;color:#ff9199;font-size:7px;font-weight:1000}
.dash-attention-list,.dash-next-list{padding:8px 12px}
.dash-attention-item,.dash-next-item{display:grid;grid-template-columns:90px minmax(130px,1fr) 100px auto;gap:8px;align-items:center;padding:9px 2px;border-top:1px solid #172e3d;font-size:7px}
.dash-attention-item:first-child,.dash-next-item:first-child{border-top:0}
.dash-attention-item strong,.dash-next-item strong{font-size:8px;color:#fff}
.dash-attention-item .reason{color:#ff9299;font-weight:900}
.dash-next-item .status{font-weight:900}
.dash-mini-pill{display:inline-flex;padding:4px 6px;border-radius:999px;border:1px solid #315064;background:#0a1c28;color:#a6bfce;font-size:6px;font-weight:900}
.dash-empty{padding:28px;text-align:center;color:#718c9e;font-size:8px}
.dash-hidden-alert{display:none!important}
@media(max-width:1200px){.dash-clean-kpis{grid-template-columns:repeat(3,1fr)}.dash-clean-grid{grid-template-columns:1fr 1fr}.dash-chart-panel:last-child{grid-column:1/-1}.dash-bottom-grid{grid-template-columns:1fr}}
@media(max-width:760px){.dash-clean-kpis{grid-template-columns:repeat(2,1fr)}.dash-clean-grid{grid-template-columns:1fr}.dash-chart-panel:last-child{grid-column:auto}.dash-donut-wrap{grid-template-columns:1fr}.dash-donut{margin:auto}}


/* ===== LIGHT / DARK MODE SWITCH ===== */
.theme-switch-wrap{
  display:flex;align-items:center;gap:6px;
  margin-left:auto;margin-right:10px;
  padding:5px 7px;
  border:1px solid var(--theme-border,#29485e);
  border-radius:999px;
  background:var(--theme-panel,#071722);
}
.theme-icon{font-size:11px;line-height:1}
.theme-switch{position:relative;width:42px;height:22px;display:inline-block}
.theme-switch input{opacity:0;width:0;height:0}
.theme-slider{
  position:absolute;inset:0;border-radius:999px;
  background:#213746;border:1px solid #395569;
  cursor:pointer;transition:.2s ease
}
.theme-slider::before{
  content:"";position:absolute;width:16px;height:16px;left:2px;top:2px;
  border-radius:50%;background:#f3f7f9;transition:.2s ease;
  box-shadow:0 1px 4px rgba(0,0,0,.25)
}
.theme-switch input:checked + .theme-slider{background:#dfe8ee;border-color:#aebcc6}
.theme-switch input:checked + .theme-slider::before{transform:translateX(20px);background:#2a3944}

/* Theme variables */
