/* ===== NOTIFICATION CENTER + TRUCK TIMELINE ===== */
.notif-center{position:relative;display:flex;align-items:center}
.notif-bell{position:relative;width:35px;height:35px;border-radius:50%;padding:0!important;font-size:14px!important}
.notif-bell b{position:absolute;right:-5px;top:-5px;min-width:17px;height:17px;padding:0 4px;border-radius:999px;background:#e33f4e;color:white!important;font-size:7px;display:grid;place-items:center;border:2px solid #071722}
.notif-panel{display:none;position:absolute;right:0;top:45px;width:390px;max-height:520px;overflow:auto;background:#071722;border:1px solid #315065;border-radius:9px;box-shadow:0 18px 45px rgba(0,0,0,.45);z-index:99999}
.notif-panel.open{display:block}
.notif-head{position:sticky;top:0;z-index:2;display:flex;justify-content:space-between;align-items:center;padding:12px;background:#091c29;border-bottom:1px solid #29485d}
.notif-head strong{font-size:9px}.notif-head small{display:block;margin-top:2px;font-size:6px;color:#7795a8}.notif-head button{font-size:17px!important;padding:1px 7px!important}
.notif-list{padding:7px}
.notif-item{display:grid;grid-template-columns:28px 1fr auto;gap:8px;padding:10px 7px;border-bottom:1px solid #183243;align-items:start}
.notif-item:last-child{border-bottom:0}.notif-ico{width:27px;height:27px;border-radius:7px;display:grid;place-items:center;background:#102b3c}
.notif-item strong{display:block;font-size:8px}.notif-item p{margin:3px 0 0;font-size:7px;color:#8ba5b5;line-height:1.45}.notif-time{font-size:6px;color:#6f8a9c}
.notif-item.danger .notif-ico{background:#42181e}.notif-item.warn .notif-ico{background:#3b2b0d}.notif-item.good .notif-ico{background:#123723}
.notif-empty{padding:35px;text-align:center;color:#7692a4;font-size:8px}
body.light-mode .notif-panel{background:#fff;border-color:#c5d7e2;box-shadow:0 15px 40px rgba(31,62,82,.18)}
body.light-mode .notif-head{background:#edf7fc;border-color:#c5d7e2}.light-mode .notif-item{border-color:#dce7ed}.light-mode .notif-ico{background:#e7f2f8}.light-mode .notif-item p{color:#647e8e}.light-mode .notif-bell b{border-color:#fff}

/* Timeline */
.timeline-modal{display:none;position:fixed;inset:0;background:rgba(0,0,0,.62);z-index:100000;align-items:center;justify-content:center;padding:20px}
.timeline-modal.open{display:flex}.timeline-dialog{width:min(900px,96vw);background:#071722;border:1px solid #315065;border-radius:10px;box-shadow:0 24px 70px rgba(0,0,0,.5)}
.timeline-head{display:flex;justify-content:space-between;align-items:center;padding:15px 18px;border-bottom:1px solid #29485d}.timeline-head strong{font-size:12px}.timeline-head small{display:block;margin-top:3px;color:#7895a7;font-size:7px}
.timeline-head button{font-size:20px!important}.timeline-steps{display:grid;grid-template-columns:repeat(7,1fr);padding:25px 18px 30px;gap:0}
.tl-step{position:relative;text-align:center;padding:0 5px}.tl-step:before{content:"";position:absolute;top:14px;left:-50%;width:100%;height:3px;background:#243d4d}.tl-step:first-child:before{display:none}
.tl-dot{position:relative;z-index:2;width:29px;height:29px;border-radius:50%;margin:0 auto 8px;background:#102533;border:3px solid #3a5668;display:grid;place-items:center;font-size:9px}
.tl-step.done:before,.tl-step.done .tl-dot{background:#1d8b50;border-color:#42c979}.tl-step.current .tl-dot{background:#126fc9;border-color:#58aff2;box-shadow:0 0 0 5px rgba(40,143,221,.15)}
.tl-step strong{display:block;font-size:7px}.tl-step small{display:block;margin-top:4px;font-size:6px;color:#7895a7}
.timeline-btn{padding:4px 7px!important;font-size:6px!important}
body.light-mode .timeline-dialog{background:#fff;border-color:#c5d7e2}.light-mode .timeline-head{border-color:#d8e4ea}.light-mode .tl-step:before{background:#d7e3ea}.light-mode .tl-dot{background:#edf4f8;border-color:#a9bfcd;color:#294454!important}
@media(max-width:900px){.notif-panel{position:fixed;right:10px;top:65px;width:calc(100vw - 20px)}.timeline-steps{grid-template-columns:1fr;gap:10px}.tl-step{display:grid;grid-template-columns:35px 1fr;text-align:left}.tl-step:before{display:none}.tl-dot{margin:0}.tl-step strong,.tl-step small{grid-column:2}}


/* ===== DVORIŠTE: KLIK NA KAMION + 360° HORIZONTALNA ROTACIJA ===== */
.yard-clickable-truck{cursor:pointer!important;pointer-events:auto!important}
.yard-clickable-truck:hover{filter:drop-shadow(0 0 10px rgba(79,255,55,.45)) drop-shadow(9px 12px 8px rgba(0,0,0,.5))!important}
#yard3DStage{touch-action:pan-y!important}


/* ===== TRUE ORBIT 360: kamera kruži oko centra, bez PAN pomicanja ===== */
#yard3DStage{
  cursor:grab!important;
  user-select:none!important;
  -webkit-user-drag:none!important;
  touch-action:none!important;
}
#yard3DStage:active{cursor:grabbing!important}
#yard3DStage .yardivo-live3d{
  transform-origin:50% 50%!important;
}


/* ===== BIRD'S-EYE 360° CAMERA =====
   Kamera ostaje iznad dvorišta; model se vrti oko centra kao maketa na stolu. */
#yard3DGround{
  transform:
    rotateX(66deg)
    rotateY(0deg)
    rotateZ(var(--yard-rz,-12deg))!important;
  transform-origin:50% 50%!important;
  transform-style:preserve-3d!important;
}
#yard3DCameraRig{
  transform-origin:50% 50%!important;
}
#yard3DStage{
  perspective:1500px!important;
  overflow:hidden!important;
  cursor:grab!important;
}
#yard3DStage.dragging{cursor:grabbing!important}


/* ===== CLEAN WHITE SCALE-MODEL SEMI TRUCK ===== */
.semi3d{width:92px!important;height:32px!important;position:relative!important;transform-style:preserve-3d!important;overflow:visible!important}
.semi3d .trailer3d{position:absolute!important;left:2px!important;top:6px!important;width:62px!important;height:21px!important;transform:none!important;background:linear-gradient(#fff,#dfe6ea)!important;border:1px solid #9eabb3!important;border-radius:2px!important;box-shadow:inset 0 -4px #bdc7cc!important}
.semi3d .trailer3d .box-face{display:none!important}
.semi3d .trailer3d:before{content:"";position:absolute;left:3px;right:-1px;top:-6px;height:7px;background:linear-gradient(#fff,#e4eaed);border:1px solid #aeb9bf;transform:skewX(-25deg);transform-origin:left bottom}
.semi3d .trailer3d:after{content:"";position:absolute;left:4px;right:4px;bottom:3px;height:2px;background:#aeb9bf;box-shadow:0 -3px 0 #edf1f3}
.semi3d .cab3d{position:absolute!important;right:2px!important;top:7px!important;width:27px!important;height:20px!important;transform:none!important;background:linear-gradient(135deg,#fff 15%,#d9e1e5)!important;border:1px solid #96a5ae!important;border-radius:6px 3px 3px 2px!important;box-shadow:inset -5px 0 #c5cfd4!important}
.semi3d .cab3d .box-face{display:none!important}
.semi3d .cab3d:before{content:"";position:absolute;right:2px;top:2px;width:9px;height:7px;background:linear-gradient(135deg,#9fc0d0,#294754);border:1px solid #607d8b;border-radius:2px}
.semi3d .cab3d:after{content:"";position:absolute;right:2px;bottom:3px;width:9px;height:4px;background:repeating-linear-gradient(#26363e 0 1px,#87979e 1px 2px);border-radius:1px}
.semi3d .cab-window{display:block!important;position:absolute!important;left:3px!important;top:3px!important;width:8px!important;height:7px!important;background:linear-gradient(135deg,#a4c4d2,#304c59)!important;border:1px solid #67828f!important;transform:none!important}
.semi3d .wheel3d{display:block!important;position:absolute!important;bottom:-2px!important;width:8px!important;height:8px!important;border-radius:50%!important;background:radial-gradient(circle,#87949b 0 20%,#202a30 22% 62%,#05090b 64%)!important;border:1px solid #05090b!important;transform:none!important;z-index:10!important}
.semi3d .w1{left:10px!important}.semi3d .w2{left:27px!important}.semi3d .w3{right:7px!important}
.yard-clickable-truck:hover{filter:drop-shadow(0 0 8px rgba(68,255,72,.55)) drop-shadow(7px 9px 5px rgba(0,0,0,.45))!important}
/* docked truck remains the same 3D miniature, never flatten it */
.docked-semi3d .semi3d{transform:translateZ(18px) scale(.82)!important;filter:drop-shadow(5px 7px 5px rgba(0,0,0,.5))!important}


/* ===== YARDIVO SMART BRAIN ===== */
.yard-brain-box{
  margin:10px 0 12px;padding:12px;border:1px solid #335a73;border-radius:8px;
  background:linear-gradient(135deg,#082238,#0a1a28);box-shadow:0 10px 25px rgba(0,0,0,.18)
}
.yard-brain-head{display:flex;justify-content:space-between;gap:12px;align-items:center}
.yard-brain-head>div{display:grid;grid-template-columns:auto 1fr;column-gap:7px;align-items:center}
