body.light-mode .yard-brain-rec strong{color:#17364a!important}

/* ===== RAMP QUEUE ===== */
.ramp-queue-panel{margin:0 0 12px;border:1px solid #29485e;border-radius:8px;background:#071722}
.ramp-queue-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;padding:10px}
.ramp-queue-card{border:1px solid #2b4c60;border-radius:7px;background:#081925;overflow:hidden}
.ramp-queue-head{display:flex;justify-content:space-between;align-items:center;padding:9px 10px;background:#0c2231}
.ramp-queue-head strong{font-size:9px}.ramp-queue-head span{font-size:6px;font-weight:1000}
