.ramp-queue-current small{font-size:6px;color:#7996a8}.ramp-queue-current strong{display:block;margin-top:3px;font-size:8px}
.ramp-queue-list{padding:0 9px 9px}
.ramp-queue-item{display:grid;grid-template-columns:24px 1fr auto;gap:7px;align-items:center;padding:7px 0;border-top:1px solid #173346;font-size:7px}
.queue-pos{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;background:#102c3d;color:#8fc8ea;font-weight:1000}
.queue-wait{font-size:6px;color:#d3a541;font-weight:900}
