.dock-live-card.ramp-config-locked .dock-live-free{opacity:.82}
.ramp-config-lock-badge{display:inline-flex;margin-top:7px;padding:4px 6px;border-radius:999px;border:1px solid #9a444c;color:#ff9da3;background:#32161b;font-size:7px;font-weight:900}


/* PRIJAM ROBE — ručni statusi */
.receiving-manual-status{margin-top:10px;padding-top:9px;border-top:1px solid rgba(130,160,180,.22)}
.receiving-manual-status>small{display:block;margin-bottom:7px;font-size:7px;font-weight:900;letter-spacing:.08em;opacity:.72}
.receiving-manual-status>div{display:flex;gap:6px;flex-wrap:wrap}
.receiving-manual-status button{padding:7px 9px;border-radius:5px;border:1px solid rgba(120,160,190,.35);font-size:8px;font-weight:900;cursor:pointer}


