/* YARDIVO STYLE: yardivo-control-tower-style */

.control-tower-kpis{display:grid;grid-template-columns:repeat(8,minmax(115px,1fr));gap:9px;margin-bottom:12px}
.control-tower-kpi{padding:12px;background:linear-gradient(180deg,#0d1c2a,#091722);border:1px solid #21394c;border-radius:8px;border-top:3px solid #2a84d8}
.control-tower-kpi small{display:block;color:#849bad;font-size:7px;font-weight:950}.control-tower-kpi strong{display:block;font-size:21px;margin-top:4px}.control-tower-kpi span{font-size:7px;color:#738b9e}
#ctDetention{color:#ff747c}#ctLate{color:#ffc05b}#ctIncidents{color:#ff7b82}
.ct-grid-main{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(310px,.65fr);gap:12px;margin-bottom:12px}
.ct-grid-secondary{display:grid;grid-template-columns:1.15fr .85fr;gap:12px}
.ct-live-table{min-width:1250px}
.ct-sla{display:inline-flex;padding:3px 7px;border-radius:999px;font-size:8px;font-weight:950}
.ct-sla.ok{background:#0d3521;border:1px solid #247245;color:#84e7a5}
.ct-sla.warn{background:#402a0d;border:1px solid #815a20;color:#ffc468}
.ct-sla.bad{background:#45151a;border:1px solid #9b3540;color:#ff9ba3}
.ct-timeline{display:flex;gap:3px;align-items:center;min-width:310px}
.ct-step{padding:3px 5px;border-radius:4px;background:#101e2a;border:1px solid #223b4e;color:#758da0;font-size:7px;font-weight:900}
.ct-step.done{background:#0d3421;border-color:#236f45;color:#85e6a4}.ct-step.current{background:#123759;border-color:#2b76b3;color:#8dcbff}
.ct-critical-list{display:grid;gap:8px;padding:12px}.ct-critical-item{padding:10px;border:1px solid #5c3920;border-left:4px solid #d88b21;border-radius:7px;background:#17130d}
.ct-critical-item.bad{border-color:#713038;border-left-color:#e04b56;background:#251015}.ct-critical-item strong{font-size:10px}.ct-critical-item span{display:block;color:#92a8b9;font-size:8px;margin-top:3px;line-height:1.45}
.ct-warehouse-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;padding:12px}
.ct-wh{padding:11px;border:1px solid #213c50;border-radius:7px;background:#091824}.ct-wh h3{margin:0;font-size:11px}.ct-wh small{color:#7891a4;font-size:8px}
.ct-wh-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-top:9px}.ct-wh-kpis div{padding:6px;background:#07141e;border:1px solid #193247;border-radius:5px;text-align:center}
.ct-wh-kpis small{display:block;font-size:7px}.ct-wh-kpis strong{display:block;margin-top:2px;font-size:13px}
.ct-supplier-risk{display:grid;gap:8px;padding:12px}.ct-supplier-row{display:grid;grid-template-columns:1fr 60px 120px;gap:9px;align-items:center;padding:8px;border:1px solid #20394c;border-radius:6px;background:#081622}
.ct-score{font-size:15px;font-weight:950;text-align:right}.ct-score.good{color:#53dc83}.ct-score.mid{color:#ffc05d}.ct-score.bad{color:#ff727a}
.ct-score-bar{height:7px;background:#07121c;border-radius:99px;overflow:hidden}.ct-score-bar i{display:block;height:100%;background:linear-gradient(90deg,#c33a43,#df9a29,#2ca85e)}
.detention-settings{margin-top:14px}.detention-settings-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;padding:14px}
.detention-settings-grid label{padding:10px;border:1px solid #274259;border-radius:7px;background:#081622}.detention-settings-grid input{width:100%;font-size:15px;font-weight:900}
.detention-note{padding:0 14px 14px;color:#8098aa;font-size:9px;line-height:1.5}
.supplier-scorecard-extra{margin-top:10px;display:grid;grid-template-columns:repeat(6,1fr);gap:7px}
.supplier-scorecard-extra div{padding:8px;background:#081622;border:1px solid #1f394c;border-radius:6px;text-align:center}
.supplier-scorecard-extra small{display:block;color:#778fa3;font-size:7px}.supplier-scorecard-extra strong{display:block;margin-top:3px;font-size:13px}
@media(max-width:1300px){.control-tower-kpis{grid-template-columns:repeat(4,1fr)}.ct-grid-main,.ct-grid-secondary{grid-template-columns:1fr}}
@media(max-width:800px){.control-tower-kpis{grid-template-columns:repeat(2,1fr)}.ct-warehouse-grid{grid-template-columns:1fr}.detention-settings-grid{grid-template-columns:1fr 1fr}.supplier-scorecard-extra{grid-template-columns:repeat(2,1fr)}}


/* YARDIVO STYLE: yardivo-manual-order-style */

.manual-order-input{display:flex;align-items:stretch;width:100%}
.manual-order-input>span{display:flex;align-items:center;padding:0 12px;border:1px solid #28516f;border-right:0;border-radius:6px 0 0 6px;background:#0d2c44;color:#7fc8ff;font-size:13px;font-weight:1000}
.manual-order-input input{flex:1;border-radius:0 6px 6px 0!important}
.order-number-inline{display:inline-flex;margin-top:4px;padding:3px 7px;border-radius:999px;border:1px solid #285f89;background:#0c2c44;color:#7fc8ff;font-size:8px;font-weight:950}
.receiving-order-number{margin-top:5px;padding:5px 7px;border-radius:5px;background:#111f2b;border:1px solid #28455a;font-size:8px}
.receiving-order-number strong{color:#7fc2ff}


/* YARDIVO STYLE: yardivo-order-search-style */

.order-search-panel{max-width:760px}
.order-search-box{display:grid;grid-template-columns:minmax(260px,1fr) auto;gap:10px;align-items:end;padding:14px}
.order-search-result{margin-top:12px}
.order-search-card{border:1px solid #28465c;border-radius:8px;background:#0a1723;overflow:hidden}
.order-search-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px;border-bottom:1px solid #20394d}
.order-search-head h2{margin:0;font-size:18px}.order-search-head small{display:block;color:#8199ac;margin-top:4px}
.order-search-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:14px}
.order-search-kpi{padding:10px;border:1px solid #20394c;background:#081521;border-radius:6px}
.order-search-kpi small{display:block;color:#7f97aa;font-size:8px;font-weight:900}.order-search-kpi strong{display:block;margin-top:4px;font-size:13px}
.order-search-timeline{padding:14px;border-top:1px solid #20394d}
.order-search-timeline h3{margin:0 0 8px;font-size:11px}
.order-search-timeline-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:7px}
.order-search-step{padding:9px;border:1px solid #20394c;border-radius:6px;background:#081521;text-align:center}
.order-search-step small{display:block;color:#778fa3;font-size:7px}.order-search-step strong{display:block;margin-top:4px;font-size:10px}
.order-search-incidents{padding:14px;border-top:1px solid #20394d}
.order-search-incidents h3{margin:0 0 8px;font-size:11px}
.order-search-empty{padding:28px;text-align:center;border:1px dashed #29465d;border-radius:8px;color:#728a9d;background:#08131e}
@media(max-width:900px){.order-search-grid{grid-template-columns:repeat(2,1fr)}.order-search-timeline-grid{grid-template-columns:1fr 1fr}.order-search-box{grid-template-columns:1fr}}


