.srp-head{padding:12px 14px;border-bottom:1px solid #203e51}.srp-head h3{margin:0;font-size:10px}.srp-head small{display:block;margin-top:3px;color:#7793a5;font-size:7px}
.srp-list{padding:10px;display:grid;gap:8px;max-height:650px;overflow:auto}
.srp-row{border:1px solid #28485b;border-radius:8px;background:#0a2130;padding:11px;cursor:pointer}
.srp-row:hover{border-color:#4c8bac}.srp-row .top{display:flex;justify-content:space-between;gap:10px}.srp-row h4{margin:0;font-size:9px}.srp-row time{font-size:7px;color:#7894a6;white-space:nowrap}
.srp-reason{margin-top:6px;font-size:8px;color:#adc0cb;line-height:1.45}.srp-change{display:flex;gap:8px;align-items:center;margin-top:8px;flex-wrap:wrap}.srp-slot{padding:5px 7px;border:1px solid #31546a;border-radius:5px;font-size:7px;background:#0c293a}.srp-arrow{color:#63acd5;font-weight:1000}
.srp-chips{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.srp-chip{padding:3px 6px;border:1px solid #315267;border-radius:999px;font-size:6px;color:#8ba8b8}.srp-chip.auto{border-color:#3b7655;color:#9cd8b2}.srp-chip.critical{border-color:#87404a;color:#ff9da6}.srp-chip.warn{border-color:#7d6730;color:#e8c66d}
.srp-detail{padding:12px}.srp-empty{padding:35px 15px;text-align:center;color:#7894a6;font-size:9px}.srp-detail h2{font-size:14px;margin:0 0 4px}.srp-detail p{font-size:8px;line-height:1.55;color:#a8bdc9}
.srp-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:10px}.srp-detail-grid div{padding:8px;border:1px solid #29485b;border-radius:6px;background:#0a2130}.srp-detail-grid small{display:block;font-size:6px;color:#7894a6}.srp-detail-grid strong{display:block;font-size:8px;margin-top:3px}
.srp-note{margin-top:10px;padding:9px;border:1px solid #29485b;border-radius:6px;background:#0a2130;font-size:8px;line-height:1.5}
.srp-action-row{display:flex;gap:7px;flex-wrap:wrap;margin-top:11px}.srp-action-row button{min-height:34px;padding:0 11px;border-radius:6px;border:1px solid #365a70;background:#0e2b3c;color:#d5e7f0;font-size:7px;font-weight:1000;cursor:pointer}
.srp-action-row .primary{border-color:#397b57;background:#113622;color:#a8eac0}

/* persistent, acknowledgment-style auto-replan alert */
#yardivoAutoReplanAlertStack{position:fixed;right:18px;top:76px;z-index:13200;width:min(470px,calc(100vw - 36px));display:grid;gap:9px}
.srp-alert{border:1px solid #4b7892;border-left:5px solid #47a7dd;border-radius:10px;background:rgba(7,24,36,.985);box-shadow:0 24px 65px rgba(0,0,0,.38),0 0 22px rgba(71,167,221,.14);padding:15px 16px;animation:srpIn .25s ease}
.srp-alert.critical{border-left-color:#df635f}.srp-alert.warn{border-left-color:#e1ad46}
.srp-alert h3{margin:0;font-size:12px;letter-spacing:.25px}.srp-alert p{font-size:9px;line-height:1.55;color:#b3c6d0;margin:7px 0}.srp-alert .change{display:grid;grid-template-columns:1fr 25px 1fr;gap:7px;align-items:center}.srp-alert .box{border:1px solid #294b60;border-radius:6px;background:#0a2130;padding:8px}.srp-alert .box small{display:block;font-size:6px;color:#7692a3}.srp-alert .box strong{display:block;font-size:8px;margin-top:3px}.srp-alert .arr{text-align:center;color:#62abd2;font-weight:1000}
.srp-alert .foot{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:10px}.srp-alert .foot small{font-size:6px;color:#708c9e}.srp-alert button{min-height:34px;padding:0 13px;border-radius:6px;border:1px solid #397b57;background:#113622;color:#a8eac0;font-size:8px;font-weight:1000;cursor:pointer}
@keyframes srpIn{from{opacity:0;transform:translateX(25px)}to{opacity:1;transform:translateX(0)}}

html[data-theme="light"] .srp-kpi,html[data-theme="light"] .srp-history,html[data-theme="light"] .srp-side,html[data-theme="light"] .srp-row,html[data-theme="light"] .srp-detail-grid div,html[data-theme="light"] .srp-note,html[data-theme="light"] .srp-alert,html[data-theme="light"] .srp-alert .box{background:#fff;color:#173448;border-color:#c7dbe5}
html[data-theme="light"] .srp-reason,html[data-theme="light"] .srp-detail p,html[data-theme="light"] .srp-alert p{color:#526f80}
@media(max-width:1050px){.srp-board{grid-template-columns:1fr}.srp-kpis{grid-template-columns:repeat(2,1fr)}}


/* YARDIVO STYLE: yardivo-live-yard-tv-v5-style */

/* =========================================================
   YARDIVO LIVE YARD TV 3D V5 — single stable renderer
   Upright warehouse / real spatial layout / office-TV safe
   ========================================================= */
#liveYardStage[data-viewmode="3d"]{
  min-height:760px!important;
  background:#03080c!important;
  overflow:hidden!important;
}
#lyTv3D{position:absolute;inset:0;overflow:hidden;background:
  radial-gradient(circle at 50% 8%,rgba(51,103,126,.18),transparent 34%),
  linear-gradient(180deg,#071117 0%,#03080c 100%);
}
.ly5-scene{position:absolute;inset:38px 12px 12px;border:1px solid #142b37;border-radius:12px;overflow:hidden;background:
  linear-gradient(180deg,#071218 0 38%,#11191d 38% 100%);
  box-shadow:inset 0 0 80px rgba(0,0,0,.35);
}
/* sky & distant tree silhouettes */
.ly5-skyline{position:absolute;left:0;right:0;top:0;height:39%;background:
 radial-gradient(ellipse at 10% 95%,#15261d 0 7%,transparent 7.5%),
 radial-gradient(ellipse at 20% 98%,#173020 0 9%,transparent 9.5%),
 radial-gradient(ellipse at 87% 96%,#13271b 0 8%,transparent 8.5%),
 radial-gradient(ellipse at 96% 100%,#172d20 0 10%,transparent 10.5%);opacity:.9}

/* upright 3D building: front + side + roof, no giant rotateX */
.ly5-building{position:absolute;left:18%;right:8%;top:8%;height:35%;z-index:8;filter:drop-shadow(0 22px 28px rgba(0,0,0,.38))}
.ly5-front{position:absolute;left:0;right:7%;top:8%;bottom:0;background:
 linear-gradient(180deg,#ffffff 0,#edf0f1 58%,#d7dde0 100%);
 border:1px solid #b6c0c5;border-radius:2px;
 clip-path:polygon(3% 6%,100% 0,100% 100%,0 100%);
}
.ly5-side{position:absolute;right:0;top:5%;width:8%;bottom:2%;background:linear-gradient(180deg,#d7dddf,#aeb8bd);
 border:1px solid #909da3;clip-path:polygon(0 0,100% 15%,100% 100%,0 97%)}
.ly5-roof{position:absolute;left:2%;right:4%;top:-4%;height:22%;background:linear-gradient(180deg,#fff,#e0e5e7);
 border:1px solid #c0c8cc;clip-path:polygon(7% 42%,94% 0,100% 42%,0 100%)}
.ly5-logo{position:absolute;left:6%;top:29%;z-index:4;color:#090d10;font-weight:1000;font-size:22px;letter-spacing:1px}
.ly5-logo .mark{font-size:38px;vertical-align:-6px;margin-right:8px}
.ly5-wh-name{position:absolute;right:11%;top:20%;z-index:4;color:#28383f;font-size:8px;font-weight:1000;letter-spacing:.8px}

/* docks sit vertically on building facade */
.ly5-docks{position:absolute;left:22%;right:14%;top:34%;height:13%;display:grid;gap:8px;z-index:15}
.ly5-dock{position:relative;background:linear-gradient(180deg,#111518,#020405);
 border:2px solid #171e22;border-radius:2px;box-shadow:0 8px 0 #353d41,0 14px 20px rgba(0,0,0,.38)}
.ly5-dock:before{content:attr(data-label);position:absolute;left:50%;top:-21px;transform:translateX(-50%);
 padding:3px 7px;border-radius:2px;background:#07090a;border:1px solid #232a2d;color:#f1f4f5;font-size:7px;font-weight:1000}
.ly5-dock:after{content:"";position:absolute;left:8%;right:8%;bottom:-13px;height:11px;background:#4c5559;
 clip-path:polygon(7% 0,93% 0,100% 100%,0 100%)}
.ly5-dock.busy{border-color:#f3a03b;box-shadow:0 0 19px rgba(243,160,59,.5),0 8px 0 #353d41}
.ly5-dock.busy .light{background:#ffa33d;box-shadow:0 0 12px #ffa33d}
.ly5-dock.closed{border-color:#dc5a64;background:#270b0e}
.ly5-dock .light{position:absolute;left:50%;top:6px;width:5px;height:5px;border-radius:50%;transform:translateX(-50%);background:#414a4e}

/* physical yard and outside area */
.ly5-yard{position:absolute;left:8%;right:7%;top:47%;bottom:6%;z-index:3;border:1px solid #293b43;border-radius:70px 70px 28px 28px;
 background:linear-gradient(180deg,#171f23,#10171b);box-shadow:inset 0 0 45px rgba(0,0,0,.22)}
.ly5-yard:before{content:"";position:absolute;left:7%;right:6%;top:53%;border-top:2px dashed rgba(235,240,242,.18)}
.ly5-yard:after{content:"";position:absolute;left:14%;right:13%;top:16%;bottom:9%;border:1px dashed rgba(80,116,132,.24);border-radius:55px}
.ly5-fence{position:absolute;left:5%;right:5%;top:44%;height:2px;background:repeating-linear-gradient(90deg,#52666f 0 8px,transparent 8px 15px);z-index:11}
.ly5-outside{position:absolute;left:1%;top:48%;bottom:7%;width:13%;z-index:5;border-right:1px dashed #52646c;background:linear-gradient(90deg,rgba(13,21,25,.8),rgba(13,21,25,.15))}
.ly5-outside-title{position:absolute;left:10px;top:9px;color:#708995;font-size:6px;font-weight:1000;letter-spacing:.8px;writing-mode:vertical-rl;transform:rotate(180deg)}
.ly5-gate{position:absolute;left:9%;bottom:18%;width:100px;height:64px;z-index:18;background:linear-gradient(145deg,#424b4f,#1c2428);border:1px solid #607078;border-radius:3px;box-shadow:0 8px 0 #0a1013}
.ly5-gate:before{content:"PORTA";position:absolute;left:10px;top:9px;color:#d4dce0;font-size:7px;font-weight:1000}
.ly5-barrier{position:absolute;left:15%;bottom:25%;width:105px;height:4px;z-index:19;background:repeating-linear-gradient(90deg,#f4f4f4 0 13px,#d43c47 13px 26px);transform:rotate(-35deg);transform-origin:left}

/* lane markings */
.ly5-path{position:absolute;height:0;border-top:2px dashed currentColor;z-index:7;opacity:.82;filter:drop-shadow(0 0 3px currentColor)}
.ly5-path.in{color:#279ce9;left:9%;width:37%;top:76%;transform:rotate(-11deg)}
.ly5-path.yard{color:#efbd36;left:41%;width:25%;top:67%;transform:rotate(-24deg)}
.ly5-path.dock{color:#ef8a29;left:56%;width:24%;top:58%;transform:rotate(-8deg)}
.ly5-path.out{color:#4bd67b;right:5%;width:24%;top:74%;transform:rotate(12deg)}

/* realistic-ish white semi truck: stable DOM model */
.ly5-truck{position:absolute;width:126px;height:52px;z-index:25;filter:drop-shadow(0 11px 8px rgba(0,0,0,.45));
 transition:left 1.7s cubic-bezier(.2,.65,.3,1),top 1.7s cubic-bezier(.2,.65,.3,1),opacity 1s ease,transform 1s ease}
.ly5-trailer{position:absolute;left:0;top:4px;width:87px;height:38px;background:linear-gradient(150deg,#fff 0,#f4f5f6 52%,#cbd3d7 100%);
 border:1px solid #919ea4;border-radius:2px;box-shadow:inset -7px -6px 0 rgba(0,0,0,.055)}
.ly5-trailer .supplier{position:absolute;left:6px;right:6px;top:11px;text-align:center;color:#111619;font-size:6px;font-weight:1000;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ly5-cab{position:absolute;right:1px;top:9px;width:39px;height:34px;background:linear-gradient(140deg,#fff,#d4dde1);border:1px solid #89979d;border-radius:5px 10px 3px 3px}
.ly5-cab:before{content:"";position:absolute;right:5px;top:4px;width:19px;height:10px;background:linear-gradient(145deg,#486d7d,#182f39);clip-path:polygon(0 0,100% 0,84% 100%,0 100%)}
.ly5-cab:after{content:"";position:absolute;right:-3px;top:19px;width:8px;height:4px;background:#edf0f1;border:1px solid #8c999e}
.ly5-wheel{position:absolute;bottom:0;width:12px;height:12px;border-radius:50%;background:#020405;border:3px solid #343c40;box-shadow:inset 0 0 0 2px #78868c}
.ly5-w1{left:15px}.ly5-w2{left:64px}.ly5-w3{right:7px}
.ly5-tag{position:absolute;left:1px;top:-22px;max-width:128px;padding:4px 6px;border-radius:4px;background:rgba(3,9,12,.95);border:1px solid #34454d;color:#f5f8f9;font-size:6px;font-weight:1000;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ly5-tag small{display:block;margin-top:1px;color:#8da2ac;font-size:5px}
/* announced/outside: visible, but intentionally not clickable */
.ly5-truck.outside{opacity:.8;animation:ly5Outside 7s ease-in-out infinite;pointer-events:none}
.ly5-truck.gate,.ly5-truck.yard,.ly5-truck.dock{cursor:pointer}
.ly5-truck.gate{animation:ly5Gate 2.4s ease-in-out infinite}
.ly5-truck.yard{animation:ly5Yard 3.1s ease-in-out infinite}
.ly5-truck.dock{animation:ly5Dock 1.15s ease-in-out infinite}
.ly5-truck.exit{animation:ly5Exit 4.2s ease forwards;pointer-events:none}
@keyframes ly5Outside{50%{transform:translateY(-4px)}}
@keyframes ly5Gate{50%{transform:translateX(6px)}}
@keyframes ly5Yard{50%{transform:translate(14px,-6px)}}
@keyframes ly5Dock{50%{filter:drop-shadow(0 0 21px rgba(243,160,59,.95)) drop-shadow(0 11px 8px rgba(0,0,0,.45))}}
@keyframes ly5Exit{to{transform:translateX(170px);opacity:0}}

/* TV UI */
.ly5-top{position:absolute;left:14px;right:14px;top:10px;z-index:50;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px}
.ly5-status{display:flex;gap:6px}.ly5-chip{padding:5px 8px;border:1px solid #28414d;border-radius:999px;background:rgba(4,14,20,.9);color:#9fb5bf;font-size:6px;font-weight:1000}.ly5-chip b{color:#fff;font-size:8px;margin-right:4px}
.ly5-title{text-align:center;color:#6f8e9d;font-size:7px;letter-spacing:1.1px;font-weight:1000}
.ly5-live{color:#75dd9a;font-size:7px;font-weight:1000}.ly5-live i{display:inline-block;width:7px;height:7px;border-radius:50%;background:#4edb80;box-shadow:0 0 11px #4edb80;margin-right:6px}
.ly5-detail{position:absolute;right:14px;top:65px;width:215px;z-index:55;padding:11px;border:1px solid #29414d;border-radius:7px;background:rgba(4,13,18,.92);backdrop-filter:blur(9px);box-shadow:0 12px 30px rgba(0,0,0,.28)}
.ly5-detail h4{margin:0 0 8px;color:#7896a5;font-size:7px;letter-spacing:.7px}.ly5-detail h3{font-size:11px;margin:0 0 7px}.ly5-detail p{font-size:7px;line-height:1.5;color:#a2b5be;margin:4px 0}.ly5-empty{color:#718b97;font-size:8px;padding:10px 0}
.ly5-outside-count{position:absolute;left:17px;bottom:14px;z-index:50;padding:7px 9px;border:1px solid #2d4652;border-radius:5px;background:rgba(3,12,17,.91);color:#8da4af;font-size:6px}.ly5-outside-count b{font-size:11px;color:#fff;margin-right:5px}


