/* V5.4 — clean TV scene: no movement arrows/paths */
#liveYardStage[data-viewmode="3d"] .ly5-path{
  display:none!important;
}

/* Docked trucks must be clearly visible in front of their assigned dock */
#liveYardStage[data-viewmode="3d"] .ly5-truck.dock{
  z-index:80!important;
  opacity:1!important;
  pointer-events:auto!important;
  animation:ly54DockPulse 1.35s ease-in-out infinite!important;
}
@keyframes ly54DockPulse{
  0%,100%{
    filter:drop-shadow(0 12px 9px rgba(0,0,0,.48));
  }
  50%{
    filter:
      drop-shadow(0 0 18px rgba(243,160,59,.75))
      drop-shadow(0 12px 9px rgba(0,0,0,.48));
  }
}

/* Dock itself glows subtly when occupied */
#liveYardStage[data-viewmode="3d"] .ly5-dock.busy{
  border-color:#f2a23d!important;
  box-shadow:
    0 0 16px rgba(242,162,61,.38),
    0 8px 0 #353d41,
    0 14px 20px rgba(0,0,0,.38)!important;
}
#liveYardStage[data-viewmode="3d"] .ly5-dock.busy .light{
  background:#ffa640!important;
  box-shadow:0 0 11px #ffa640!important;
}

/* Keep visual stacking clean around facade */
#liveYardStage[data-viewmode="3d"] .ly5-building{z-index:8!important}
#liveYardStage[data-viewmode="3d"] .ly5-docks{z-index:25!important}
#liveYardStage[data-viewmode="3d"] .ly5-yard{z-index:3!important}


