/* YARDIVO STYLE: yardivo-v583-live-yard-pro-final-css */

/* ==========================================================
   LIVE YARD · PROFESSIONAL OPERATIONS VIEW
   Clean top-down control board, no game-like 3D styling.
   ========================================================== */
#liveYard{
  --ly-bg:#0b141c;
  --ly-panel:#111c25;
  --ly-panel2:#16232d;
  --ly-line:#2a3c49;
  --ly-text:#e9f1f6;
  --ly-muted:#8298a8;
  --ly-green:#25cf6b;
  --ly-red:#ef4d55;
  --ly-amber:#f2ad43;
}
#liveYard .section-title{
  margin-bottom:12px!important;
}
#liveYard .live-yard-top{
  background:var(--ly-panel)!important;
  border:1px solid var(--ly-line)!important;
  border-radius:10px!important;
  padding:10px!important;
  box-shadow:none!important;
}
#liveYard .ly-strip{
  display:grid!important;
  grid-template-columns:repeat(6,minmax(95px,1fr))!important;
  gap:8px!important;
  margin:10px 0!important;
}
#liveYard .ly-kpi{
  background:var(--ly-panel)!important;
  border:1px solid var(--ly-line)!important;
  border-radius:9px!important;
  padding:10px 12px!important;
  box-shadow:none!important;
  transition:border-color .12s ease,background-color .12s ease!important;
}
#liveYard .ly-kpi strong{font-size:18px!important;color:#fff!important}
#liveYard .ly-kpi small{color:var(--ly-muted)!important;letter-spacing:.05em!important}
#liveYard .ly-layout{
  display:grid!important;
  grid-template-columns:minmax(0,1fr) 300px!important;
  gap:12px!important;
}
#liveYard .ly-stage,
#liveYard .ly-side{
  background:var(--ly-panel)!important;
  border:1px solid var(--ly-line)!important;
  border-radius:11px!important;
  box-shadow:none!important;
}
#liveYard .ly-stage{
  overflow:hidden!important;
}
#liveYard .ly-stage-head{
  min-height:42px!important;
  display:flex!important;
  align-items:center!important;
  padding:0 14px!important;
  background:#0e1922!important;
  color:#9eb0bd!important;
  border-bottom:1px solid var(--ly-line)!important;
  font-size:9px!important;
  font-weight:900!important;
  letter-spacing:.04em!important;
}

/* Disable game-like 3D presentation. 2D and 3D toggle now share professional top-down language. */
#liveYardStage[data-viewmode="2d"] .ly-yard,
#liveYardStage[data-viewmode="3d"] .ly-yard{
  position:relative!important;
  min-height:600px!important;
  overflow:hidden!important;
  transform:none!important;
  perspective:none!important;
  background:
    linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px),
    #0b151d!important;
  background-size:28px 28px!important;
  border:0!important;
}

/* Facility */
#liveYard .ly-warehouse{
  position:absolute!important;
  left:5%!important;right:5%!important;top:4%!important;height:74px!important;
  background:#17232c!important;
  border:1px solid #314754!important;
  border-radius:8px!important;
  box-shadow:none!important;
  transform:none!important;
}
#liveYard .ly-warehouse-title{
  color:#c8d5de!important;
  font-size:10px!important;
  font-weight:950!important;
  letter-spacing:.06em!important;
}

/* Dock row */
#liveYard .ly-docks{
  position:absolute!important;
  left:8%!important;right:8%!important;top:14%!important;
  height:72px!important;
  display:grid!important;
  gap:9px!important;
  z-index:8!important;
}
#liveYard .ly-dock{
  position:relative!important;
  min-height:58px!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  border-radius:8px!important;
  font-size:11px!important;
  font-weight:1000!important;
  letter-spacing:.04em!important;
  color:#eaf7ef!important;
  background:#103322!important;
  border:2px solid #22b95e!important;
  box-shadow:0 0 0 1px rgba(37,207,107,.08)!important;
  animation:yvDockFreePulse 1.8s ease-in-out infinite!important;
  transform:none!important;
}
#liveYard .ly-dock::after{
  content:"SLOBODNA";
  position:absolute;
  bottom:5px;left:0;right:0;
  color:#68e79b;
  font-size:6px;
  font-weight:1000;
  letter-spacing:.09em;
}
#liveYard .ly-dock.busy{
  color:#fff!important;
  background:#3a1519!important;
  border-color:#e84b53!important;
  box-shadow:0 0 0 1px rgba(239,77,85,.12)!important;
  animation:yvDockBusyPulse 1.35s ease-in-out infinite!important;
}
#liveYard .ly-dock.busy::after{
  content:"ZAUZETA";
  color:#ff8c92;
}
#liveYard .ly-dock .dock-timer{
  position:absolute!important;
  top:5px!important;right:7px!important;
  color:#ffb6ba!important;
  font-size:6px!important;
}
@keyframes yvDockFreePulse{
  0%,100%{box-shadow:0 0 0 1px rgba(37,207,107,.08),0 0 0 rgba(37,207,107,0)}
  50%{box-shadow:0 0 0 1px rgba(37,207,107,.22),0 0 16px rgba(37,207,107,.22)}
}
@keyframes yvDockBusyPulse{
  0%,100%{box-shadow:0 0 0 1px rgba(239,77,85,.10),0 0 0 rgba(239,77,85,0)}
  50%{box-shadow:0 0 0 1px rgba(239,77,85,.24),0 0 15px rgba(239,77,85,.20)}
}

/* Operational road / gate / parking zone */
#liveYard .ly-road{
  position:absolute!important;
  left:7%!important;right:7%!important;top:34%!important;height:30%!important;
  background:#18232a!important;
  border:1px solid #2f404a!important;
  border-radius:10px!important;
  box-shadow:none!important;
}
#liveYard .ly-road::after{
  content:"";
  position:absolute;left:4%;right:4%;top:50%;height:2px;
  background:repeating-linear-gradient(90deg,#66747d 0 20px,transparent 20px 38px);
  opacity:.6;
}
#liveYard .ly-gate{
  position:absolute!important;
  left:5%!important;bottom:7%!important;
  width:128px!important;height:44px!important;
  display:flex!important;align-items:center!important;justify-content:center!important;
  border:1px solid #3f6075!important;
  border-radius:8px!important;
  background:#10202c!important;
  color:#9fc2d8!important;
  font-size:8px!important;font-weight:1000!important;
  box-shadow:none!important;
}
#liveYard .ly-wait-zone{
  position:absolute!important;
  right:6%!important;bottom:7%!important;
  width:36%!important;height:126px!important;
  border:1px dashed #526774!important;
  border-radius:9px!important;
  background:#101a21!important;
  color:#8fa2af!important;
  box-shadow:none!important;
}
#liveYard .ly-wait-zone::before{
  content:"PARKING / BUFFER";
  position:absolute;left:10px;top:8px;
  font-size:7px;font-weight:1000;letter-spacing:.08em;color:#93a8b6;
}
#liveYard .ly-wait-zone>span{display:none!important}

/* Trucks become clean operations markers instead of game pieces. */
#liveYard .ly-truck{
  min-width:132px!important;
  max-width:170px!important;
  min-height:48px!important;
  padding:8px 10px!important;
  border-radius:8px!important;
  background:#172631!important;
  border:1px solid #3a5364!important;
  box-shadow:0 5px 16px rgba(0,0,0,.18)!important;
  color:#eaf1f5!important;
  transform:none!important;
  transition:border-color .12s ease,background-color .12s ease!important;
  z-index:20!important;
}
#liveYard .ly-truck::before{
  content:"";
  position:absolute;left:0;top:0;bottom:0;width:4px;
  border-radius:8px 0 0 8px;
  background:#6f8fa3;
}
#liveYard .ly-truck strong{
  display:block!important;
  font-size:8px!important;
  font-weight:1000!important;
  white-space:nowrap!important;
  overflow:hidden!important;
  text-overflow:ellipsis!important;
}
#liveYard .ly-truck small{
  display:block!important;
  margin-top:3px!important;
  color:#9aafbd!important;
  font-size:7px!important;
  white-space:nowrap!important;
}
#liveYard .ly-truck.late{border-color:#e69b3a!important}
#liveYard .ly-truck.late::before{background:#e69b3a!important}
#liveYard .ly-truck.incident{border-color:#e84b53!important}
#liveYard .ly-truck.incident::before{background:#e84b53!important}
#liveYard .ly-truck.done{opacity:.5!important}

/* Planned route from parked truck to dock. */
#liveYard .yv-yard-route-layer{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  pointer-events:none;
  z-index:14;
  overflow:visible;
}
#liveYard .yv-yard-route-path{
  fill:none;
  stroke:#57a7d8;
  stroke-width:3;
  stroke-linecap:round;
  stroke-linejoin:round;
  stroke-dasharray:9 8;
  opacity:.92;
  animation:yvRouteDash 1.35s linear infinite;
}
#liveYard .yv-yard-route-label{
  position:absolute;
  z-index:18;
  pointer-events:none;
  padding:4px 7px;
  border:1px solid #447795;
  border-radius:6px;
  background:#102638;
  color:#a9d8f6;
  font-size:6px;
  font-weight:1000;
  letter-spacing:.05em;
  white-space:nowrap;
}
@keyframes yvRouteDash{to{stroke-dashoffset:-34}}

/* Side details */
#liveYard .ly-side{overflow:hidden!important}
#liveYard .ly-side-head{
  padding:13px 14px!important;
  background:#0e1922!important;
  border-bottom:1px solid var(--ly-line)!important;
}
#liveYard .ly-side-head h3{font-size:10px!important;color:#e6eef3!important}
#liveYard .ly-side-head small{color:#7f95a5!important}
#liveYard .ly-detail{padding:14px!important}
#liveYard .ly-detail-grid{
  display:grid!important;grid-template-columns:1fr 1fr!important;gap:8px!important;
}
#liveYard .ly-detail-grid>div,
#liveYard .ly-next-row{
  background:#121f29!important;
  border:1px solid #293d4b!important;
  border-radius:7px!important;
  padding:9px!important;
}

/* Light theme: professional white control board. */
html[data-yardivo-main-theme="light"] #liveYard{
  --ly-bg:#f3f6f9;--ly-panel:#fff;--ly-panel2:#f7fafc;--ly-line:#d6e1e9;--ly-text:#183247;--ly-muted:#6c8191;
}
html[data-yardivo-main-theme="light"] #liveYard .live-yard-top,
html[data-yardivo-main-theme="light"] #liveYard .ly-kpi,
html[data-yardivo-main-theme="light"] #liveYard .ly-stage,
html[data-yardivo-main-theme="light"] #liveYard .ly-side,
html[data-yardivo-main-theme="light"] #liveYard .ly-stage-head,
html[data-yardivo-main-theme="light"] #liveYard .ly-side-head{
  background:#fff!important;color:#183247!important;border-color:#d6e1e9!important;
}
html[data-yardivo-main-theme="light"] #liveYardStage .ly-yard{
  background:
    linear-gradient(rgba(32,61,80,.035) 1px,transparent 1px),
    linear-gradient(90deg,rgba(32,61,80,.035) 1px,transparent 1px),
    #f4f7f9!important;
  background-size:28px 28px!important;
}
html[data-yardivo-main-theme="light"] #liveYard .ly-warehouse{background:#eef3f6!important;border-color:#c8d5de!important}
html[data-yardivo-main-theme="light"] #liveYard .ly-warehouse-title{color:#29465a!important}
html[data-yardivo-main-theme="light"] #liveYard .ly-road{background:#e9eef1!important;border-color:#cbd7df!important}
