html[data-yardivo-main-theme="light"] #liveYard .ly-truck{
  background:#fff!important;color:#1d374a!important;border-color:#aebfcb!important;box-shadow:0 4px 14px rgba(27,56,76,.08)!important;
}
html[data-yardivo-main-theme="light"] #liveYard .ly-truck small{color:#657d8d!important}
html[data-yardivo-main-theme="light"] #liveYard .ly-detail-grid>div,
html[data-yardivo-main-theme="light"] #liveYard .ly-next-row{background:#f7fafc!important;border-color:#d6e1e9!important}

@media(max-width:1050px){
  #liveYard .ly-layout{grid-template-columns:1fr!important}
  #liveYard .ly-side{min-height:220px}
}


/* YARDIVO STYLE: yardivo-v583-live-yard-3d-twin-css */

/* ==========================================================
   YARDIVO LIVE YARD · 3D DIGITAL TWIN ENGINE
   Original visual language: professional isometric YMS view.
   ========================================================== */

#liveYardStage[data-viewmode="3d"]{
  background:#0b141c!important;
}
#liveYardStage[data-viewmode="3d"] #lyCanvas{
  min-height:690px!important;
  background:#08121a!important;
  overflow:hidden!important;
  position:relative!important;
}
.yv3-scene{
  position:relative;
  min-height:690px;
  overflow:hidden;
  background:
    radial-gradient(circle at 50% 0%,rgba(38,105,147,.18),transparent 36%),
    linear-gradient(180deg,#0b1822 0%,#071018 100%);
  color:#e9f1f6;
  perspective:1500px;
  isolation:isolate;
}
.yv3-hud{
  position:absolute;left:18px;right:18px;top:16px;
  display:flex;align-items:center;justify-content:space-between;gap:14px;
  z-index:50;pointer-events:none;
}
.yv3-hud-left,.yv3-hud-right{
  display:flex;align-items:center;gap:8px;flex-wrap:wrap;
}
.yv3-title{
  display:grid;gap:3px;
  padding:10px 13px;
  border:1px solid #294252;
  border-radius:9px;
  background:rgba(8,20,29,.88);
  backdrop-filter:blur(8px);
}
.yv3-title strong{font-size:10px;color:#fff;letter-spacing:.08em}
.yv3-title small{font-size:7px;color:#7f9aaa}
.yv3-chip{
  min-height:34px;padding:0 10px;border-radius:8px;
  display:inline-flex;align-items:center;gap:6px;
  background:rgba(9,23,33,.90);
  border:1px solid #294252;
  color:#a8bbc8;font-size:7px;font-weight:950;
  backdrop-filter:blur(8px);
}
.yv3-chip b{font-size:11px;color:#fff}
.yv3-live i{
  width:7px;height:7px;border-radius:50%;background:#2dd36f;
  box-shadow:0 0 12px rgba(45,211,111,.65);
  animation:yv3Live 1.5s ease-in-out infinite;
}
@keyframes yv3Live{50%{opacity:.45;box-shadow:0 0 4px rgba(45,211,111,.25)}}

/* Camera/world */
.yv3-camera{
  position:absolute;
  left:50%;
  top:51%;
  width:1030px;
  height:610px;
  transform:translate(-50%,-50%);
  perspective:1400px;
  z-index:5;
}
.yv3-world{
  position:absolute;
  left:50%;top:50%;
  width:900px;height:500px;
  transform-style:preserve-3d;
  transform:translate(-50%,-45%) rotateX(58deg) rotateZ(-29deg);
  transform-origin:center center;
}
.yv3-ground{
  position:absolute;inset:0;
  transform-style:preserve-3d;
  border:1px solid #314652;
  border-radius:16px;
  background:
    linear-gradient(rgba(255,255,255,.017) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.017) 1px,transparent 1px),
    #18242b;
  background-size:28px 28px;
  box-shadow:0 52px 90px rgba(0,0,0,.48),inset 0 0 65px rgba(0,0,0,.18);
}

/* Roads */
.yv3-road{
  position:absolute;
  background:#242f34;
  border:1px solid #34444c;
  box-shadow:inset 0 0 0 2px rgba(255,255,255,.008);
}
.yv3-road.main{left:6%;right:6%;top:55%;height:21%;border-radius:8px}
.yv3-road.spine{left:64%;top:12%;width:13%;height:72%;border-radius:8px}
.yv3-road.main::after{
  content:"";position:absolute;left:3%;right:3%;top:50%;height:2px;
  background:repeating-linear-gradient(90deg,#c4ac50 0 18px,transparent 18px 39px);
  opacity:.55;
}
.yv3-road.spine::after{
  content:"";position:absolute;top:4%;bottom:4%;left:50%;width:2px;
  background:repeating-linear-gradient(180deg,#c4ac50 0 18px,transparent 18px 39px);
  opacity:.55;
}

/* Parking */
.yv3-parking{
  position:absolute;
  left:4%;top:15%;width:49%;height:31%;
  transform:translateZ(2px);
  border:1px solid #344953;
  border-radius:8px;
  background:#1d292f;
  padding:8px;
}
.yv3-parking-title{
  position:absolute;left:9px;top:7px;
  font-size:7px;font-weight:1000;color:#849aa6;letter-spacing:.08em;
}
.yv3-parking-grid{
  position:absolute;left:8px;right:8px;top:27px;bottom:8px;
  display:grid;grid-template-columns:repeat(8,1fr);gap:5px;
}
.yv3-slot{
  position:relative;
  border:1px solid #566a74;
  border-top:0;
  background:rgba(255,255,255,.01);
}
.yv3-slot::after{
  content:attr(data-slot);
  position:absolute;left:3px;bottom:2px;
  font-size:5px;color:#617984;font-weight:900;
}

/* Gate */
.yv3-gate{
  position:absolute;
  left:5%;bottom:7%;
  width:115px;height:42px;
  transform:translateZ(5px);
  display:flex;align-items:center;justify-content:center;
  border:1px solid #40667c;
  border-radius:7px;
  background:#10202a;
  color:#8fb9cf;
  font-size:7px;font-weight:1000;letter-spacing:.08em;
}

/* Warehouse 3D volume */
.yv3-building{
  position:absolute;
  right:4%;top:6%;
  width:27%;height:43%;
  transform-style:preserve-3d;
  transform:translateZ(10px);
}
.yv3-building-front{
  position:absolute;left:0;right:0;top:14%;bottom:0;
  background:linear-gradient(180deg,#38474e,#29363c);
  border:1px solid #56666d;
  transform:translateZ(34px);
  box-shadow:9px 12px 18px rgba(0,0,0,.24);
}
.yv3-building-side{
  position:absolute;right:-38px;top:14%;width:38px;bottom:0;
  transform-origin:left center;
  transform:rotateY(90deg) translateZ(34px);
  background:#222e34;border:1px solid #45565e;
}
.yv3-building-roof{
  position:absolute;left:0;right:0;top:0;height:55px;
  transform-origin:bottom center;
  transform:rotateX(90deg) translateZ(21px);
  background:linear-gradient(145deg,#7b898e,#515f65);
  border:1px solid #8f9ca1;
}
.yv3-building-name{
  position:absolute;left:0;right:0;top:24%;
  transform:translateZ(38px) rotateX(-58deg) rotateZ(29deg);
  text-align:center;
  color:#dce6ea;font-size:8px;font-weight:1000;letter-spacing:.07em;
  pointer-events:none;
}

/* Docks attached to warehouse face */
.yv3-docks{
  position:absolute;
  right:31%;top:12%;
