}
.yv3-dock.busy::before{
  background:#ff626a;box-shadow:0 0 9px rgba(255,98,106,.9);
}
.yv3-dock.closed{
  background:#272c30;border-color:#69747a;color:#98a4aa;animation:none;
}
.yv3-dock.closed::before{background:#77838a;box-shadow:none}
@keyframes yv3DockFree{50%{box-shadow:0 0 20px rgba(38,201,104,.28),inset 0 -5px 0 rgba(0,0,0,.15)}}
@keyframes yv3DockBusy{50%{box-shadow:0 0 20px rgba(239,80,88,.28),inset 0 -5px 0 rgba(0,0,0,.15)}}

/* Trucks */
.yv3-truck{
  position:absolute;
  width:76px;height:25px;
  transform-style:preserve-3d;
  transform:translateZ(12px);
  z-index:15;
  cursor:pointer;
}
.yv3-trailer{
