.yv3-cab::before{
  content:"";position:absolute;left:4px;top:2px;width:11px;height:5px;
  background:#17384a;border-radius:1px;
}
.yv3-wheel{
  position:absolute;bottom:-3px;width:7px;height:7px;border-radius:50%;
