/* YARDIVO STYLE: yardivo-v28-hybrid-yard-style */

/* Both Live Yard and War Room expose the same large, clickable 2D / 3D switch. */
#yardivoFinalLiveYard .yf-toolbar,#yardivoFinalWarYard .yf-toolbar{z-index:1200!important;pointer-events:auto!important}
#yardivoFinalLiveYard .yf-toolbar button,#yardivoFinalWarYard .yf-toolbar button{min-width:48px;height:32px;font-size:10px;pointer-events:auto!important;position:relative;z-index:1201}
#yardivoFinalLiveYard .yf-stage,#yardivoFinalWarYard .yf-stage{perspective:none!important}

/* 2D = clean operational top-down plan. */
.yf-world.mode2d{transform:translate(-50%,-50%) scale(.88)!important;transform-style:flat!important}
.yf-world.mode2d .yf-floor{transform-style:flat!important}
.yf-world.mode2d .yf-building{transform:none!important;box-shadow:0 10px 22px #0008}
.yf-world.mode2d .yf-building .roof,.yf-world.mode2d .yf-building .side{display:none!important}
.yf-world.mode2d .yf-ramp{transform:none!important;box-shadow:0 5px 8px #0007}
.yf-world.mode2d .yf-truck{transform:rotate(var(--truck-r,0deg))!important;filter:drop-shadow(4px 5px 4px #0008)!important}

/* 3D HYBRID = FLOOR STAYS 2D. Only warehouse, ramps and trucks get volume. */
.yf-world.mode3d{transform:translate(-50%,-50%) rotateZ(var(--yf-rz,-8deg)) scale(var(--yf-scale,.84))!important;transform-style:flat!important}
.yf-world.mode3d .yf-floor{transform-style:flat!important;box-shadow:0 28px 55px #000c,inset 0 0 75px #0008!important}
.yf-world.mode3d .yf-building{transform:none!important;filter:drop-shadow(18px 22px 15px #0009);z-index:8}
.yf-world.mode3d .yf-building .front{background:linear-gradient(180deg,#e7ebe9 0 68%,#a3ada7 69% 100%)!important;box-shadow:inset 0 -22px 0 #89948e,0 14px 20px #0007!important}
