.yf-world.mode3d .yf-building .side{display:block!important;right:-31px!important;top:5px!important;width:32px!important;height:171px!important;transform:skewY(-38deg)!important;transform-origin:left top!important;background:linear-gradient(90deg,#8d9992,#626d67)!important}
