/* YARDIVO STYLE: yardivo-light-green-choice-style-20260831 */

/* ===== LIGHT MODE STYLE CHOICE: CLASSIC WHITE / GREEN-WHITE ===== */
#yardivoLightStyleSettings{
  display:none;
  margin-bottom:12px;
}
body[data-yardivo-role="admin"] #yardivoLightStyleSettings,
body[data-yardivo-role="inventory"] #yardivoLightStyleSettings,
body[data-yardivo-role="reception"] #yardivoLightStyleSettings{
  display:block!important;
}
body[data-yardivo-role="gate"] #yardivoLightStyleSettings{display:none!important}

.yardivo-light-style-options{
  display:grid;
  grid-template-columns:repeat(2,minmax(180px,260px));
  gap:10px;
  margin-top:10px;
}
.yardivo-light-style-option{
  position:relative;
  min-height:88px;
  padding:13px 14px;
  border:1px solid #d4dce1;
  border-radius:9px;
  cursor:pointer;
  user-select:none;
  transition:.16s ease;
}
.yardivo-light-style-option input{
  position:absolute;
  opacity:0;
  pointer-events:none;
}
.yardivo-light-style-option strong{display:block;font-size:12px;margin-bottom:5px}
.yardivo-light-style-option small{display:block;line-height:1.45}
.yardivo-light-style-option.white{
  background:linear-gradient(145deg,#ffffff,#f2f4f5);
  color:#20282e;
}
.yardivo-light-style-option.green{
  background:linear-gradient(145deg,#f7fff9,#e6f7eb);
  color:#153e26;
  border-color:#acd7b8;
}
.yardivo-light-style-option.selected{
  outline:2px solid #7f8b93;
  outline-offset:1px;
}
.yardivo-light-style-option.green.selected{
  outline-color:#34a85d;
}
.yardivo-light-style-note{margin-top:9px;color:#75838c;font-size:9px}
@media(max-width:650px){
  .yardivo-light-style-options{grid-template-columns:1fr}
}

