/* YARDIVO STYLE: yardivo-overview-3d-carousel-style-20260831 */

/* ===== OVERVIEW 3D SUPPLIER BAR CAROUSEL ===== */
#overviewSupplier3D{
  margin:14px 0 18px;
  padding:14px;
  border:1px solid var(--theme-border,#29485e);
  border-radius:12px;
  background:linear-gradient(180deg,var(--theme-panel,#071722),var(--theme-panel-2,#0a1a26));
  overflow:hidden;
}
#overviewSupplier3D .ov3d-head{
  display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap;
  margin-bottom:12px;
}
#overviewSupplier3D .ov3d-head h2{margin:0;font-size:14px}
#overviewSupplier3D .ov3d-head small{display:block;margin-top:4px}
#overviewSupplier3D .ov3d-controls{display:flex;gap:7px;align-items:center}
#overviewSupplier3D .ov3d-controls button{
  min-width:42px;height:36px;border-radius:8px;border:1px solid var(--theme-border,#29485e);
  background:var(--theme-panel-2,#0a1a26);color:var(--theme-text,#e9f1f5);
  cursor:pointer;font-weight:1000;
}
#overviewSupplier3D .ov3d-stage{
  position:relative;
  min-height:360px;
  perspective:1100px;
  perspective-origin:50% 44%;
  overflow:hidden;
  border:1px solid var(--theme-border-soft,#1d3749);
  border-radius:12px;
  background:
    radial-gradient(circle at 50% 30%,rgba(255,255,255,.045),transparent 38%),
    linear-gradient(180deg,rgba(255,255,255,.018),transparent 70%);
  touch-action:pan-y;
}
#overviewSupplier3D .ov3d-world{
  position:absolute;left:50%;top:52%;
  width:860px;height:280px;
  transform-style:preserve-3d;
  transform:translate(-50%,-50%) rotateX(62deg) rotateZ(var(--ov3d-rz,-11deg));
  transition:transform .28s ease;
}
#overviewSupplier3D .ov3d-floor{
  position:absolute;inset:18px 40px 14px;
  transform:translateZ(-10px);
  border:1px solid var(--theme-border,#29485e);
  border-radius:14px;
  background:
    repeating-linear-gradient(90deg,transparent 0 84px,rgba(255,255,255,.035) 85px 86px),
    repeating-linear-gradient(0deg,transparent 0 54px,rgba(255,255,255,.03) 55px 56px),
    rgba(0,0,0,.10);
}
#overviewSupplier3D .ov3d-bars{
  position:absolute;inset:0 50px 8px;
  display:flex;align-items:flex-end;justify-content:center;gap:22px;
  transform-style:preserve-3d;
}
#overviewSupplier3D .ov3d-item{
  width:76px;height:236px;position:relative;transform-style:preserve-3d;cursor:pointer;
}
#overviewSupplier3D .ov3d-bar3{
  position:absolute;left:18px;bottom:38px;width:40px;
  height:var(--h,60px);
  transform-style:preserve-3d;
  transition:height .35s ease,filter .2s ease,transform .2s ease;
}
#overviewSupplier3D .ov3d-item:hover .ov3d-bar3,
#overviewSupplier3D .ov3d-item.selected .ov3d-bar3{
  transform:translateZ(8px);
  filter:brightness(1.08);
}
#overviewSupplier3D .ov3d-face{
  position:absolute;box-sizing:border-box;border:1px solid rgba(255,255,255,.12);
}
#overviewSupplier3D .ov3d-front{
  inset:0;
  background:var(--bar,#2fb96b);
  transform:translateZ(11px);
}
#overviewSupplier3D .ov3d-side{
  top:0;right:-22px;width:22px;height:100%;
  background:color-mix(in srgb,var(--bar,#2fb96b) 72%,#000);
  transform-origin:left center;transform:rotateY(90deg);
}
#overviewSupplier3D .ov3d-top{
  left:0;top:-22px;width:40px;height:22px;
  background:color-mix(in srgb,var(--bar,#2fb96b) 88%,#fff);
  transform-origin:left bottom;transform:rotateX(90deg);
}
#overviewSupplier3D .ov3d-score{
  position:absolute;left:50%;bottom:4px;transform:translateX(-50%);
  min-width:58px;padding:5px 6px;border-radius:999px;
  border:1px solid var(--theme-border,#29485e);
  background:var(--theme-panel,#071722);color:var(--theme-text,#e9f1f5);
  text-align:center;font-size:9px;font-weight:1000;
}
#overviewSupplier3D .ov3d-name{
  position:absolute;left:50%;bottom:-23px;transform:translateX(-50%) rotateZ(11deg);
  width:105px;text-align:center;font-size:7px;line-height:1.2;
  color:var(--theme-muted,#7f9bad);font-weight:900;
}
#overviewSupplier3D .ov3d-detail{
  display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;
  margin-top:12px;
}
#overviewSupplier3D .ov3d-kpi{
  padding:9px 10px;border:1px solid var(--theme-border-soft,#1d3749);
  border-radius:8px;background:var(--theme-card,#091a27);
}
#overviewSupplier3D .ov3d-kpi small{display:block;font-size:7px;color:var(--theme-muted,#7f9bad)}
#overviewSupplier3D .ov3d-kpi strong{display:block;margin-top:3px;font-size:13px}
#overviewSupplier3D .ov3d-hint{
  margin-top:9px;font-size:7px;color:var(--theme-muted,#7f9bad);text-align:center;
}
body.light-mode #overviewSupplier3D{
  background:#fff!important;border-color:#d5dce1!important;
}
body.light-mode #overviewSupplier3D .ov3d-stage{
  background:linear-gradient(180deg,#f8faf9,#eef3ef)!important;
  border-color:#d6ded9!important;
}
body.light-mode #overviewSupplier3D .ov3d-floor{
  background:
    repeating-linear-gradient(90deg,transparent 0 84px,rgba(25,70,40,.04) 85px 86px),
    repeating-linear-gradient(0deg,transparent 0 54px,rgba(25,70,40,.035) 55px 56px),
    #eef4ef!important;
  border-color:#d3ded6!important;
}
body.light-mode #overviewSupplier3D .ov3d-score,
body.light-mode #overviewSupplier3D .ov3d-kpi{
  background:#fff!important;color:#183324!important;border-color:#d3ded6!important;
}
body.light-mode.yardivo-light-green #overviewSupplier3D{
  border-color:#cfe1d3!important;
}
body.light-mode.yardivo-light-green #overviewSupplier3D .ov3d-stage{
  background:linear-gradient(180deg,#fbfefc,#edf7ef)!important;
  border-color:#cfe1d3!important;
}
body.light-mode.yardivo-light-green #overviewSupplier3D .ov3d-score{
  border-color:#abd3b5!important;color:#1e6339!important;
}
@media(max-width:850px){
  #overviewSupplier3D .ov3d-world{width:720px;transform:translate(-50%,-50%) rotateX(62deg) rotateZ(var(--ov3d-rz,-8deg)) scale(.84)}
  #overviewSupplier3D .ov3d-detail{grid-template-columns:repeat(2,1fr)}
}
@media(max-width:560px){
  #overviewSupplier3D .ov3d-stage{min-height:320px}
  #overviewSupplier3D .ov3d-world{width:620px;scale:.73}
  #overviewSupplier3D .ov3d-detail{grid-template-columns:1fr 1fr}
}
@media(prefers-reduced-motion:reduce){
  #overviewSupplier3D .ov3d-world,#overviewSupplier3D .ov3d-bar3{transition:none!important}
}


