/* YARDIVO STYLE: yardivo-professional-redesign-v1-20260831 */

:root{
 --yv-bg:#f3f6f4;--yv-surface:#fff;--yv-surface2:#f8faf9;--yv-line:#dce5df;
 --yv-text:#17231d;--yv-muted:#6c7c73;--yv-brand:#167a4a;--yv-brand2:#0e6239;
 --yv-soft:#eaf5ee;--yv-danger:#c84049;--yv-warn:#b87917;
 --yv-shadow:0 10px 30px rgba(24,50,36,.07);--yv-shadow-lg:0 24px 60px rgba(19,44,30,.12);
 --yv-r:12px;--yv-rs:8px;
}
body{background:var(--yv-bg)!important;color:var(--yv-text)!important;font-family:Inter,"SF Pro Display","Segoe UI",Arial,sans-serif!important;letter-spacing:-.008em}
body:not(.light-mode){--yv-bg:#101612;--yv-surface:#171f1a;--yv-surface2:#1c2620;--yv-line:#2a3930;--yv-text:#edf4ef;--yv-muted:#95a59b;--yv-brand:#42b879;--yv-brand2:#67cc94;--yv-soft:#183326;--yv-shadow:0 12px 34px #0004;--yv-shadow-lg:0 24px 60px #0006}
body.yardivo-dark-graphite:not(.light-mode){--yv-bg:#111312;--yv-surface:#1a1d1b;--yv-surface2:#202421;--yv-line:#313632;--yv-text:#f1f3f1;--yv-muted:#a0a6a2;--yv-brand:#64b785;--yv-soft:#213129}

/* Shell */
.sidebar,#sidebar{background:var(--yv-surface)!important;border-right:1px solid var(--yv-line)!important;box-shadow:none!important}
.topbar,.top-bar,#topbar{background:color-mix(in srgb,var(--yv-surface) 94%,transparent)!important;border-bottom:1px solid var(--yv-line)!important;box-shadow:0 4px 18px rgba(18,45,30,.035)!important;backdrop-filter:blur(18px)}
.main,.main-content,#mainContent{background:var(--yv-bg)!important}
.logo,.brand,.sidebar-brand{letter-spacing:-.04em!important;font-weight:950!important}
.sidebar .nav-item,.sidebar [data-view],.sidebar [data-home-target],nav [data-view]{
 border-radius:8px!important;margin:2px 8px!important;min-height:38px!important;padding:9px 11px!important;
 color:var(--yv-muted)!important;font-weight:760!important;transition:.16s ease!important;border:1px solid transparent!important
}
.sidebar .nav-item:hover,.sidebar [data-view]:hover,.sidebar [data-home-target]:hover,nav [data-view]:hover{
 background:var(--yv-surface2)!important;color:var(--yv-text)!important;transform:translateX(1px)
}
.sidebar .active,.sidebar [data-view].active,.sidebar [data-home-target].active,nav [data-view].active{
 background:var(--yv-soft)!important;color:var(--yv-brand)!important;border-color:color-mix(in srgb,var(--yv-brand) 18%,transparent)!important;box-shadow:none!important
}

/* Typography */
.page-title,.view-title,h1{font-weight:900!important;letter-spacing:-.035em!important}
h2,h3,.panel-title,.card-title{letter-spacing:-.02em!important}
.page-subtitle,.subtitle,.muted,.text-muted{color:var(--yv-muted)!important}

/* Universal surfaces */
.card,.panel,.section-card,.settings-card,.kpi-card,.metric-card,.summary-card,.report-card,.overview-card,
[class*="kpi-card"],[class*="metric-card"],[class*="summary-card"]{
 background:var(--yv-surface)!important;border:1px solid var(--yv-line)!important;border-radius:var(--yv-r)!important;
 box-shadow:var(--yv-shadow)!important
}
.panel-head,.card-head,.section-head{border-bottom:1px solid var(--yv-line)!important;background:transparent!important}
.kpi-value,.metric-value,.stat-value{font-weight:920!important;letter-spacing:-.035em!important}

/* Buttons */
button,.btn,[role="button"]{font-family:inherit}
.btn,button:not(.nav-item):not(.icon-btn){
 border-radius:8px!important;font-weight:820!important;letter-spacing:-.01em!important;transition:transform .14s ease,box-shadow .14s ease,background .14s ease!important
}
.btn:hover,button:not(.nav-item):not(.icon-btn):hover{transform:translateY(-1px)}
.btn-primary,.primary,.btn-save,[class*="btn-primary"]{background:var(--yv-brand)!important;border-color:var(--yv-brand)!important;color:#fff!important;box-shadow:0 6px 16px color-mix(in srgb,var(--yv-brand) 22%,transparent)!important}
.btn-secondary,.secondary{background:var(--yv-surface)!important;color:var(--yv-text)!important;border:1px solid var(--yv-line)!important}
.logout-btn,[class*="logout"]{background:transparent!important;color:var(--yv-danger)!important;border:1px solid color-mix(in srgb,var(--yv-danger) 30%,var(--yv-line))!important}

/* Forms */
input,select,textarea{
 background:var(--yv-surface)!important;color:var(--yv-text)!important;border:1px solid var(--yv-line)!important;
 border-radius:8px!important;box-shadow:none!important;min-height:40px
}
input:focus,select:focus,textarea:focus{outline:none!important;border-color:var(--yv-brand)!important;box-shadow:0 0 0 3px color-mix(in srgb,var(--yv-brand) 12%,transparent)!important}
label{color:var(--yv-muted)!important;font-weight:760!important}

/* Tables */
table{border-collapse:separate!important;border-spacing:0!important;background:var(--yv-surface)!important;border:1px solid var(--yv-line)!important;border-radius:10px!important;overflow:hidden}
thead th{background:var(--yv-surface2)!important;color:var(--yv-muted)!important;text-transform:uppercase!important;font-size:10px!important;letter-spacing:.055em!important;border-bottom:1px solid var(--yv-line)!important}
tbody td{border-bottom:1px solid var(--yv-line)!important}
tbody tr:hover td{background:color-mix(in srgb,var(--yv-brand) 4%,var(--yv-surface))!important}

/* Chips and status */
.badge,.chip,.pill,[class*="status-chip"],[class*="status-pill"]{border-radius:999px!important;font-weight:820!important;box-shadow:none!important}
.warehouse-badge,.location-badge,.user-chip{background:var(--yv-surface2)!important;color:var(--yv-text)!important;border:1px solid var(--yv-line)!important;border-radius:999px!important}

/* Modals */
.modal,.modal-content,.dialog,.drawer,.side-panel{background:var(--yv-surface)!important;color:var(--yv-text)!important;border:1px solid var(--yv-line)!important;border-radius:14px!important;box-shadow:var(--yv-shadow-lg)!important}

/* Home/dashboard */
.home-card,.menu-card,[data-home-target]{border-radius:12px!important}
.dashboard-grid,.kpi-grid{gap:12px!important}

/* Operational recommendations: clean professional green */
.notice-result,.recommendation-card,.smart-recommendation,[class*="recommendation"]{
 border-radius:10px!important;box-shadow:none!important
}

/* My Yard / War Room framed as premium digital-twin modules */
#myYard .myy-shell,#yardivoWarRoom .war-room-shell,#yardivoWarRoom{
 border-radius:14px!important;border:1px solid var(--yv-line)!important;box-shadow:var(--yv-shadow-lg)!important;overflow:hidden
}
#yardivoMyYardWebGL,#yardivoWarRoomWebGL{border-radius:10px!important}
#yardivoMyYardWebGL .my3-hud,#yardivoWarRoomWebGL .wr3-hud{
 border-radius:999px!important;box-shadow:0 8px 24px rgba(0,0,0,.12)!important
}

/* Scrollbars */
*{scrollbar-width:thin;scrollbar-color:color-mix(in srgb,var(--yv-muted) 35%,transparent) transparent}
::-webkit-scrollbar{width:8px;height:8px}::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--yv-muted) 32%,transparent);border-radius:20px}

/* Professional spacing */
.view,.app-view,.page-section{animation:yvViewIn .18s ease both}
@keyframes yvViewIn{from{opacity:.5;transform:translateY(3px)}to{opacity:1;transform:none}}
@media(max-width:900px){
 .sidebar .nav-item,.sidebar [data-view],.sidebar [data-home-target]{margin:1px 5px!important}
 .card,.panel,.section-card{border-radius:10px!important}
}
@media(prefers-reduced-motion:reduce){.view,.app-view,.page-section{animation:none!important}}

/* Login refinement without changing workflow */
#loginOverlay{backdrop-filter:blur(18px)}
#loginOverlay .login-card,#loginOverlay>div>div{
 border-radius:16px!important;border:1px solid var(--yv-line)!important;box-shadow:var(--yv-shadow-lg)!important
}


/* YARDIVO STYLE: yardivo-professional-redesign-v2-20260831 */

/* YARDIVO Professional UX v2 — premium logistics control-system refinement */
:root{
 --yv2-green:#147a49;--yv2-green2:#0c5b35;--yv2-mint:#eef8f2;--yv2-ink:#14231b;
 --yv2-sub:#718077;--yv2-border:#dbe5df;--yv2-canvas:#f2f6f3;
 --yv2-blue:#2777d8;--yv2-amber:#c78b25;--yv2-red:#d34b54;
}
body.light-mode{background:linear-gradient(180deg,#f8faf9 0,#f2f6f3 240px)!important}
body.light-mode .main,body.light-mode .main-content,body.light-mode #mainContent{background:transparent!important}

/* Top chrome: quieter, more expensive-looking */
.topbar,.top-bar,#topbar{
 min-height:64px!important;padding-left:22px!important;padding-right:22px!important;
 box-shadow:0 1px 0 rgba(20,60,38,.04),0 10px 30px rgba(24,50,36,.025)!important
}
.topbar:after,.top-bar:after,#topbar:after{
 content:"";position:absolute;left:0;right:0;bottom:-1px;height:1px;
 background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--yv-brand) 28%,transparent),transparent);pointer-events:none
}

/* Sidebar: stronger information architecture */
.sidebar,#sidebar{padding-top:10px!important}
.sidebar .logo,.sidebar .brand,.sidebar-brand{
 padding:12px 16px 18px!important;font-size:20px!important;color:var(--yv-text)!important
}
.sidebar .logo:after,.sidebar .brand:after,.sidebar-brand:after{
 content:"YARD MANAGEMENT SYSTEM";display:block;margin-top:4px;font-size:7px;letter-spacing:.16em;font-weight:850;color:var(--yv-muted)
}
.sidebar .nav-section-title,.sidebar .nav-label,.sidebar small{
 font-size:8px!important;letter-spacing:.13em!important;text-transform:uppercase!important;color:var(--yv-muted)!important;font-weight:900!important
}
.sidebar .nav-item,.sidebar [data-view],.sidebar [data-home-target]{
 position:relative!important;font-size:12px!important
}
.sidebar .active:before,.sidebar [data-view].active:before,.sidebar [data-home-target].active:before{
 content:"";position:absolute;left:-8px;top:8px;bottom:8px;width:3px;border-radius:0 4px 4px 0;background:var(--yv-brand)
}

/* Content widths & vertical rhythm */
.view,.app-view,.page-section{padding-top:22px!important}
.view>h1,.app-view>h1,.page-section>h1,.page-title{margin-bottom:5px!important}
.page-title{font-size:25px!important;line-height:1.08!important}
.page-subtitle,.subtitle{font-size:11px!important}

/* Cards: flatter by default, elevation on interaction */
.card,.panel,.section-card,.settings-card,.kpi-card,.metric-card,.summary-card,.overview-card{
 transition:border-color .16s ease,box-shadow .16s ease,transform .16s ease!important
}
.card:hover,.kpi-card:hover,.metric-card:hover,.summary-card:hover{
 border-color:color-mix(in srgb,var(--yv-brand) 24%,var(--yv-line))!important;
 box-shadow:0 13px 32px rgba(18,49,32,.09)!important
}
body:not(.light-mode) .card:hover,body:not(.light-mode) .kpi-card:hover{box-shadow:0 13px 32px rgba(0,0,0,.26)!important}

/* KPI visual hierarchy */
.kpi-card,.metric-card,.summary-card{position:relative!important;overflow:hidden!important;padding:16px!important}
.kpi-card:after,.metric-card:after,.summary-card:after{
 content:"";position:absolute;left:0;top:0;bottom:0;width:2px;background:color-mix(in srgb,var(--yv-brand) 70%,transparent);opacity:.65
}
.kpi-value,.metric-value,.stat-value{font-size:clamp(22px,2vw,31px)!important;line-height:1!important}
.kpi-label,.metric-label,.stat-label{font-size:8px!important;letter-spacing:.075em!important;text-transform:uppercase!important;color:var(--yv-muted)!important;font-weight:900!important}

/* Buttons: compact enterprise controls */
.btn,button:not(.nav-item):not(.icon-btn){min-height:36px!important;padding:8px 13px!important}
.btn-primary,.primary,.btn-save,[class*="btn-primary"]{
 background:linear-gradient(180deg,color-mix(in srgb,var(--yv-brand) 94%,white),var(--yv-brand2))!important;
 box-shadow:0 7px 16px color-mix(in srgb,var(--yv-brand) 18%,transparent)!important
}
.btn-primary:active,.primary:active{transform:translateY(0)!important;box-shadow:none!important}

/* Forms: more refined */
input,select,textarea{font-size:12px!important}
input::placeholder,textarea::placeholder{color:color-mix(in srgb,var(--yv-muted) 72%,transparent)!important}
select{cursor:pointer}

/* Tables: sticky, clean operations console */
.table-wrap,.table-container{border-radius:11px!important}
thead th{position:sticky;top:0;z-index:2;padding-top:11px!important;padding-bottom:11px!important}
tbody td{padding-top:10px!important;padding-bottom:10px!important;font-size:11px!important}
tbody tr:last-child td{border-bottom:0!important}

/* Status semantics across the app */
[class*="status"][class*="green"],.status-ok,.status-done,.status-received{background:#e8f6ee!important;color:#147347!important;border-color:#bfe3cf!important}
[class*="status"][class*="red"],.status-late,.status-error{background:#fbecee!important;color:#b83842!important;border-color:#efc4c8!important}
[class*="status"][class*="amber"],.status-waiting,.status-warning{background:#fff5e4!important;color:#99630c!important;border-color:#efd7a8!important}

/* Home menu tiles */
#homeMenu .card,#homeMenu .menu-card,#homeMenu [data-home-target]{
 position:relative!important;overflow:hidden!important;min-height:112px!important;
 background:linear-gradient(145deg,var(--yv-surface),color-mix(in srgb,var(--yv-brand) 3%,var(--yv-surface)))!important
}
#homeMenu .card:after,#homeMenu .menu-card:after,#homeMenu [data-home-target]:after{
 content:"";position:absolute;width:74px;height:74px;right:-28px;bottom:-30px;border-radius:50%;
 background:color-mix(in srgb,var(--yv-brand) 6%,transparent);pointer-events:none
}

/* Digital Twin framing */
#myYard .myy-stage,#yardivoWarRoom #wrYardCanvas{
 border:1px solid color-mix(in srgb,var(--yv-brand) 20%,var(--yv-line))!important;
 box-shadow:inset 0 0 0 1px rgba(255,255,255,.04),0 18px 42px rgba(20,52,34,.10)!important
}
#yardivoMyYardWebGL .my3-hud,#yardivoWarRoomWebGL .wr3-hud{
 text-transform:uppercase!important;letter-spacing:.06em!important
}

/* Settings become a proper admin console */
#settings .settings-card,#settings .card{
 box-shadow:none!important;border-color:var(--yv-line)!important
}
#settings .settings-card:hover,#settings .card:hover{border-color:color-mix(in srgb,var(--yv-brand) 28%,var(--yv-line))!important}

/* Modal hierarchy */
.modal-content,.dialog,.drawer,.side-panel{
 overflow:hidden!important
}
.modal-content h2,.modal-content h3,.dialog h2,.dialog h3{font-weight:900!important;letter-spacing:-.025em!important}

/* Better focus accessibility */
button:focus-visible,a:focus-visible,[tabindex]:focus-visible{
 outline:2px solid var(--yv-brand)!important;outline-offset:2px!important
}

/* Subtle operational live indicator */
#myYard .my3-hud i,#yardivoWarRoom .wr3-hud i{
 animation:yvLivePulse 2.2s ease-in-out infinite
}
@keyframes yvLivePulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.5;transform:scale(.72)}}

/* Login premium polish */
#loginOverlay .login-card,#loginOverlay>div>div{
 background:color-mix(in srgb,var(--yv-surface) 96%,transparent)!important;
 backdrop-filter:blur(24px)!important
}
#loginOverlay input,#loginOverlay select{min-height:44px!important}
#loginOverlay button{min-height:42px!important}

/* Responsive density */
@media(max-width:1100px){
 .page-title{font-size:22px!important}
 .kpi-card,.metric-card,.summary-card{padding:13px!important}
}
@media(max-width:700px){
 .view,.app-view,.page-section{padding:14px!important}
 .topbar,.top-bar,#topbar{padding-left:12px!important;padding-right:12px!important}
 .card,.panel,.section-card{box-shadow:none!important}
}


