/* YARDIVO STYLE: yardivo-v583-macos-motion-ui-style */

/* ============================================================
   YARDIVO MOTION SYSTEM · macOS-inspired opening behavior
   ============================================================ */
:root{
  --y-motion-fast:160ms;
  --y-motion-open:360ms;
  --y-motion-ease:cubic-bezier(.20,.88,.24,1);
  --y-motion-spring:cubic-bezier(.16,1,.30,1);
}

/* Native dialogs */
dialog[open]{
  animation:yardivoDialogOpen var(--y-motion-open) var(--y-motion-spring) both;
  transform-origin:50% 44%;
}
dialog::backdrop{
  animation:yardivoBackdropIn 220ms ease-out both;
}
@keyframes yardivoDialogOpen{
  0%{opacity:0;transform:translateY(12px) scale(.935);filter:blur(7px)}
  58%{opacity:1;transform:translateY(-1px) scale(1.008);filter:blur(0)}
  100%{opacity:1;transform:translateY(0) scale(1);filter:blur(0)}
}
@keyframes yardivoBackdropIn{
  from{opacity:0}
  to{opacity:1}
}

/* Custom overlay modals already controlled by .open */
.timeline-modal.open .timeline-dialog,
#yardivoIncidentImageModal.open .yiv-dialog,
#yardivoNotifReaderV5.open .y5-reader,
#yardivoRampModal.open .yod-dialog,
#yardivoReceivingModal.open .yod-dialog,
.yardivo-motion-overlay.open > :not(.yardivo-motion-ignore){
  animation:yardivoPanelOpen var(--y-motion-open) var(--y-motion-spring) both;
  transform-origin:50% 42%;
}
.timeline-modal.open,
#yardivoIncidentImageModal.open,
#yardivoNotifReaderV5.open,
#yardivoRampModal.open,
#yardivoReceivingModal.open{
  animation:yardivoOverlayIn 210ms ease-out both;
}
@keyframes yardivoPanelOpen{
  0%{opacity:0;transform:translateY(16px) scale(.94);filter:blur(8px)}
  62%{opacity:1;transform:translateY(-2px) scale(1.006);filter:blur(0)}
  100%{opacity:1;transform:none;filter:none}
}
@keyframes yardivoOverlayIn{
  from{background-color:rgba(2,9,15,0);backdrop-filter:blur(0)}
}

/* ============================================================
   ANNOUNCEMENT DETAIL · floating app window above Daily/Weekly
   ============================================================ */
#announcementDetail.active{
  position:fixed!important;
  inset:0!important;
  z-index:12550!important;
  display:flex!important;
  flex-direction:column!important;
  align-items:center!important;
  justify-content:flex-start!important;
  gap:0!important;
  padding:clamp(14px,3vh,30px)!important;
  overflow:auto!important;
  overscroll-behavior:contain;
  background:rgba(3,9,12,.72)!important;
  backdrop-filter:blur(13px) saturate(.86)!important;
  -webkit-backdrop-filter:blur(13px) saturate(.86)!important;
  animation:yardivoAnnouncementBackdrop 220ms ease-out both;
}
#announcementDetail.active > .section-title,
#announcementDetail.active > .announcement-detail-wrap{
  width:min(1180px,calc(100vw - 30px))!important;
  max-width:1180px!important;
  box-sizing:border-box!important;
  background:var(--theme-panel,#0a1720)!important;
}
#announcementDetail.active > .section-title{
  position:sticky!important;
  top:0!important;
  z-index:2!important;
  margin:0!important;
  padding:18px 20px!important;
  border:1px solid var(--theme-border,#315064)!important;
  border-bottom:0!important;
  border-radius:16px 16px 0 0!important;
  box-shadow:0 22px 65px rgba(0,0,0,.30)!important;
  animation:yardivoAnnouncementWindow var(--y-motion-open) var(--y-motion-spring) both;
  transform-origin:50% 38%;
}
#announcementDetail.active > .announcement-detail-wrap{
  margin:0 0 28px!important;
  padding:0 18px 20px!important;
  border:1px solid var(--theme-border,#315064)!important;
  border-top:0!important;
  border-radius:0 0 16px 16px!important;
  box-shadow:0 32px 95px rgba(0,0,0,.52)!important;
  animation:yardivoAnnouncementBody 410ms var(--y-motion-spring) both;
  transform-origin:50% 0;
}
#announcementDetail.active .announcement-detail-hero{
  margin-top:3px!important;
  border-radius:12px!important;
}
#announcementDetail.active .panel{
  border-radius:11px!important;
}
#announcementDetail.active #backFromAnnouncementDetail{
  min-width:112px;
  border-radius:999px!important;
}
@keyframes yardivoAnnouncementBackdrop{
  0%{opacity:0;backdrop-filter:blur(0) saturate(1)}
  100%{opacity:1}
}
@keyframes yardivoAnnouncementWindow{
  0%{opacity:0;transform:translateY(24px) scale(.91);filter:blur(10px)}
  56%{opacity:1;transform:translateY(-3px) scale(1.008);filter:blur(0)}
  100%{opacity:1;transform:translateY(0) scale(1);filter:none}
}
@keyframes yardivoAnnouncementBody{
  0%{opacity:0;transform:translateY(26px) scale(.925);filter:blur(8px)}
  62%{opacity:1;transform:translateY(-1px) scale(1.004);filter:blur(0)}
  100%{opacity:1;transform:none;filter:none}
}

/* tiny opening response for dropdown/popover-like UI */
.notification-dropdown:not([hidden]),
.dropdown-menu.open,
.context-menu.open{
