/* YARDIVO STYLE: yardivo-v583-warehouse-transition-style */

/* ============================================================
   YARDIVO WAREHOUSE CONTEXT TRANSITION
   Wxxx -> Wyyy = content exits left, new content enters right
   ============================================================ */
:root{
  --yardivo-wh-transition-out:150ms;
  --yardivo-wh-transition-in:210ms;
  --yardivo-wh-ease:cubic-bezier(.22,.72,.24,1);
}

/* Main application content only; topbar/context stays visually anchored. */
#main.yardivo-wh-exit,
.main.yardivo-wh-exit,
main.yardivo-wh-exit,
.app-main.yardivo-wh-exit{
  animation:yardivoWhExit var(--yardivo-wh-transition-out) cubic-bezier(.4,0,.7,.2) both!important;
  pointer-events:none;
}

#main.yardivo-wh-enter,
.main.yardivo-wh-enter,
main.yardivo-wh-enter,
.app-main.yardivo-wh-enter{
  animation:yardivoWhEnter var(--yardivo-wh-transition-in) var(--yardivo-wh-ease) both!important;
}

@keyframes yardivoWhExit{
  0%{opacity:1;transform:translateX(0);filter:blur(0)}
  100%{opacity:.12;transform:translateX(-11px);filter:blur(1.5px)}
}
@keyframes yardivoWhEnter{
  0%{opacity:.08;transform:translateX(12px);filter:blur(1.8px)}
  72%{opacity:1;transform:translateX(-1px);filter:blur(0)}
  100%{opacity:1;transform:translateX(0);filter:blur(0)}
}

/* Small response in the global warehouse context itself. */
#yardivoGlobalContext.yardivo-wh-context-pulse{
  animation:yardivoWhContextPulse 280ms cubic-bezier(.2,.85,.25,1) both;
}
@keyframes yardivoWhContextPulse{
  0%{transform:scale(.992);opacity:.82}
  55%{transform:scale(1.004);opacity:1}
  100%{transform:scale(1);opacity:1}
}

#ygcWarehouseName.yardivo-wh-name-enter{
  animation:yardivoWhNameIn 260ms cubic-bezier(.18,.9,.25,1) both;
}
@keyframes yardivoWhNameIn{
  0%{opacity:0;transform:translateY(4px)}
  100%{opacity:1;transform:none}
}

/* Keep modal/detail overlays stable if warehouse is changed elsewhere. */
body.yardivo-wh-switching dialog[open],
body.yardivo-wh-switching #announcementDetail.active,
body.yardivo-wh-switching .timeline-modal.open{
  animation:none!important;
}

/* Accessibility */
@media(prefers-reduced-motion:reduce){
  #main.yardivo-wh-exit,
  .main.yardivo-wh-exit,
  main.yardivo-wh-exit,
  .app-main.yardivo-wh-exit,
  #main.yardivo-wh-enter,
  .main.yardivo-wh-enter,
  main.yardivo-wh-enter,
  .app-main.yardivo-wh-enter,
  #yardivoGlobalContext.yardivo-wh-context-pulse,
  #ygcWarehouseName.yardivo-wh-name-enter{
    animation:none!important;
    transform:none!important;
    filter:none!important;
    opacity:1!important;
  }
}


