/* YARDIVO STYLE: yardivo-map-live-delay-visual-v1 */

/* ==========================================================
   DNEVNA + TJEDNA MAPA · LIVE STATUS VISUALS
   U dolasku = plava
   Kašnjenje = plava kartica + progresivni glow (žuto → narančasto → crveno)
   NO-SHOW = puna crvena
   Odbijen = puna bordo
   Zaprimljen = puna zelena
   ========================================================== */

@keyframes yardivoDelayPulseSoft{
  0%,100%{filter:saturate(1);transform:translateZ(0)}
  50%{filter:saturate(1.14);transform:translateZ(0)}
}
@keyframes yardivoDelayPulseHard{
  0%,100%{filter:brightness(1);transform:translateZ(0)}
  50%{filter:brightness(1.08);transform:translateZ(0)}
}

/* Clean baseline */
#dailyMapBoard .dmv-booked,
#weeklyMapBoard .week-map-item{
  transition:background .22s ease,border-color .22s ease,box-shadow .22s ease,color .22s ease!important;
}

/* In transit remains blue. */
#dailyMapBoard .dmv-booked.status-u-dolasku:not([class*="yv-delay-level-"]),
#weeklyMapBoard .week-map-item.status-u-dolasku:not([class*="yv-delay-level-"]){
  background:#0e5fa8!important;
  border-color:#238ce9!important;
  color:#fff!important;
  box-shadow:none!important;
}

/* Delay level 1: just started — blue remains dominant, yellow perimeter glow. */
#dailyMapBoard .dmv-booked.yv-delay-level-1,
#weeklyMapBoard .week-map-item.yv-delay-level-1{
  background:linear-gradient(135deg,#0e5fa8 0%,#0e5fa8 76%,#665715 100%)!important;
  border:2px solid #f4d24b!important;
  color:#fff!important;
  box-shadow:0 0 0 1px rgba(244,210,75,.25),0 0 9px rgba(244,210,75,.30)!important;
  animation:yardivoDelayPulseSoft 2.2s ease-in-out infinite!important;
}
/* Delay level 2: amber. */
#dailyMapBoard .dmv-booked.yv-delay-level-2,
#weeklyMapBoard .week-map-item.yv-delay-level-2{
  background:linear-gradient(135deg,#0d568f 0%,#715213 78%,#8a5a10 100%)!important;
  border:2px solid #f2ae38!important;
  color:#fff!important;
  box-shadow:0 0 0 1px rgba(242,174,56,.27),0 0 11px rgba(242,174,56,.38)!important;
  animation:yardivoDelayPulseSoft 1.9s ease-in-out infinite!important;
}
/* Delay level 3: orange/red. */
#dailyMapBoard .dmv-booked.yv-delay-level-3,
#weeklyMapBoard .week-map-item.yv-delay-level-3{
  background:linear-gradient(135deg,#744114 0%,#973413 72%,#a72c18 100%)!important;
  border:2px solid #ff7a35!important;
  color:#fff!important;
  box-shadow:0 0 0 1px rgba(255,122,53,.28),0 0 13px rgba(255,98,45,.43)!important;
  animation:yardivoDelayPulseSoft 1.6s ease-in-out infinite!important;
}
/* Delay level 4: strong red. */
#dailyMapBoard .dmv-booked.yv-delay-level-4,
#weeklyMapBoard .week-map-item.yv-delay-level-4{
  background:linear-gradient(135deg,#8e2719 0%,#b52222 72%,#bd1e28 100%)!important;
  border:2px solid #ff4e4e!important;
  color:#fff!important;
  box-shadow:0 0 0 1px rgba(255,78,78,.30),0 0 15px rgba(255,55,55,.48)!important;
  animation:yardivoDelayPulseHard 1.35s ease-in-out infinite!important;
}
/* Delay level 5: near NO-SHOW — deepest live-red glow. */
#dailyMapBoard .dmv-booked.yv-delay-level-5,
#weeklyMapBoard .week-map-item.yv-delay-level-5{
  background:linear-gradient(135deg,#991b22 0%,#c31726 68%,#d1182b 100%)!important;
  border:2px solid #ff3b4e!important;
  color:#fff!important;
  box-shadow:0 0 0 1px rgba(255,59,78,.34),0 0 19px rgba(255,35,55,.56)!important;
  animation:yardivoDelayPulseHard 1.08s ease-in-out infinite!important;
}

/* NO-SHOW = clearly red, full card. */
#dailyMapBoard .dmv-booked.status-no-show,
#dailyMapBoard .dmv-booked.status-nije-dosao,
#weeklyMapBoard .week-map-item.status-no-show,
#weeklyMapBoard .week-map-item.status-nije-dosao{
  background:#c61d2b!important;
  border:2px solid #ff5060!important;
  color:#fff!important;
  box-shadow:0 0 0 1px rgba(255,80,96,.26),0 0 14px rgba(220,28,45,.32)!important;
  animation:none!important;
}

/* ODBIJEN = bordo, intentionally distinct from NO-SHOW red. */
#dailyMapBoard .dmv-booked.status-odbijen,
#weeklyMapBoard .week-map-item.status-odbijen{
  background:#64151d!important;
  border:2px solid #9f3c48!important;
  color:#ffecee!important;
  box-shadow:inset 4px 0 0 #bd4b58!important;
  animation:none!important;
}

/* ZAPRIMLJEN = green. */
#dailyMapBoard .dmv-booked.status-zaprimljeno,
#weeklyMapBoard .week-map-item.status-zaprimljeno{
  background:#126b34!important;
  border:2px solid #32bc67!important;
  color:#fff!important;
  box-shadow:0 0 0 1px rgba(50,188,103,.15)!important;
  animation:none!important;
}

/* Existing operational states remain clear. */
#dailyMapBoard .dmv-booked.status-u-dvorištu,
#weeklyMapBoard .week-map-item.status-u-dvorištu{
  background:#a94f0d!important;border-color:#f28a2d!important;color:#fff!important;
}
#dailyMapBoard .dmv-booked.status-na-rampi,
#weeklyMapBoard .week-map-item.status-na-rampi{
  background:#8b6d0a!important;border-color:#e8c238!important;color:#fff!important;
}
#dailyMapBoard .dmv-booked.status-promijenjena,
#weeklyMapBoard .week-map-item.status-promijenjena{
  background:#6340a8!important;border-color:#9a74e4!important;color:#fff!important;
}

/* Make live delay text legible on all intensities. */
#dailyMapBoard .booking-delay-detail,
#weeklyMapBoard .statusline{
  font-weight:950!important;
}
#dailyMapBoard .booking-delay-detail{
  display:inline-flex!important;
  width:max-content!important;
  max-width:100%!important;
  padding:2px 6px!important;
  border-radius:999px!important;
  background:rgba(0,0,0,.24)!important;
  color:#fff!important;
  font-size:7px!important;
}

/* Respect reduced motion while keeping the severity color. */
@media (prefers-reduced-motion:reduce){
  #dailyMapBoard [class*="yv-delay-level-"],
  #weeklyMapBoard [class*="yv-delay-level-"]{animation:none!important}
}


