/* YARDIVO STYLE: yardivo-v583-operational-chat-style */

#yardivoOpChatFab{position:fixed;right:18px;bottom:76px;z-index:2147481200;display:none;align-items:center;gap:7px;border:1px solid #39769a;border-radius:12px;background:#0c2637;color:#eaf7fd;padding:10px 12px;font:900 10px/1 Arial,sans-serif;box-shadow:0 14px 38px rgba(0,0,0,.35);cursor:pointer}
#yardivoOpChatFab .yoc-badge{display:none;min-width:20px;height:20px;padding:0 6px;border-radius:10px;background:#ed4b57;color:#fff;align-items:center;justify-content:center}
#yardivoOpChatPanel{position:fixed;right:16px;top:78px;z-index:2147482500;width:min(430px,calc(100vw - 32px));height:min(690px,calc(100vh - 96px));display:none;grid-template-rows:auto auto 1fr auto;border:1px solid #31586e;border-radius:16px;background:#0a1d29;color:#eef8fd;box-shadow:0 24px 80px rgba(0,0,0,.48);overflow:hidden}
#yardivoOpChatPanel.open{display:grid}.yoc-head{display:flex;align-items:center;gap:10px;padding:13px 14px;border-bottom:1px solid #27485c;background:#0d2432}.yoc-close{margin-left:auto;width:32px;height:32px;border:1px solid #31566b;border-radius:8px;background:#102b3a;color:#fff;font-size:18px}
.yoc-tabs{display:flex;gap:6px;overflow:auto;padding:9px;border-bottom:1px solid #244457;background:#081923}.yoc-tabs button{white-space:nowrap;border:1px solid #294c61;border-radius:9px;background:#0d2533;color:#9eb7c5;padding:8px 9px;font-size:8px;font-weight:950}.yoc-tabs button.active{background:#174867;border-color:#3b8dbb;color:#fff}.yoc-tabs em{font-style:normal;margin-left:4px;background:#e84b57;color:#fff;border-radius:8px;padding:1px 5px}
.yoc-msgs{overflow:auto;padding:12px;display:flex;flex-direction:column;gap:8px}.yoc-empty{margin:auto;color:#718d9d;font-size:10px;text-align:center;padding:25px}.yoc-msg{max-width:86%;padding:9px 10px;border:1px solid #294b5e;border-radius:12px;background:#102837;align-self:flex-start}.yoc-msg.mine{align-self:flex-end;background:#164565;border-color:#317ba7}.yoc-msg .who{font-size:7px;color:#77a1b7;margin-bottom:4px;font-weight:900}.yoc-msg .body{font-size:10px;line-height:1.45;white-space:pre-wrap}.yoc-msg .at{margin-top:4px;color:#64879a;font-size:7px;text-align:right}
.yoc-compose{display:grid;grid-template-columns:1fr auto;gap:7px;padding:10px;border-top:1px solid #27485c;background:#0d2432}.yoc-compose textarea{resize:none;min-height:44px;max-height:90px;border:1px solid #31566c;border-radius:9px;background:#071822;color:#fff;padding:9px;font-size:10px}.yoc-compose button{border:1px solid #3691c4;border-radius:9px;background:#147bb5;color:#fff;padding:0 13px;font-weight:950}
#yardivoOpChatPopupStack{position:fixed;right:14px;top:88px;z-index:2147482450;width:min(340px,calc(100vw - 28px));display:grid;gap:8px;pointer-events:none}.yoc-pop{pointer-events:auto;border:1px solid #39708d;border-radius:12px;background:#0c2433;color:#eef8fd;padding:11px 12px;box-shadow:0 14px 36px rgba(0,0,0,.38);cursor:pointer;animation:yocIn .18s ease-out}.yoc-pop strong{display:block;font-size:10px}.yoc-pop small{display:block;margin-top:3px;color:#78a0b5;font-size:7px;font-weight:900}.yoc-pop p{margin:6px 0 0;font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}@keyframes yocIn{from{opacity:0;transform:translateX(20px)}to{opacity:1;transform:none}}
